type Page = "lab" | "dashboard" | "builder" | "chart" | "backtest" | "observation" | "daytrade" | "paper" | "execution" | "activity";
type RuleDetail = { logic: "AND" | "OR" | "NOT"; comparator: "이상" | "초과" | "이하" | "미만" | "상향돌파" | "하향돌파"; period: number; threshold: number; unit: "%" | "원" | "억원" };
type Rule = { id: string; title: string; subtitle: string; tone: "aqua" | "violet" | "amber" | "blue"; enabled: boolean; weight: number; detail?: RuleDetail };
type ExpressionTree = { id: string; logic: RuleDetail["logic"]; children: Array<string | ExpressionTree> };

const isExpressionTree = (item: string | ExpressionTree): item is ExpressionTree => typeof item !== "string";
const initialExpressionTree = (rules: Rule[]): ExpressionTree => ({ id: "root-group", logic: "AND", children: rules.map(rule => rule.id) });
const removeRuleFromTree = (tree: ExpressionTree, ruleId: string): ExpressionTree => ({ ...tree, children: tree.children.filter(child => child !== ruleId).map(child => isExpressionTree(child) ? removeRuleFromTree(child, ruleId) : child) });
const moveRuleToGroup = (tree: ExpressionTree, groupId: string, ruleId: string): ExpressionTree => {
  const withoutRule = removeRuleFromTree(tree, ruleId);
  const insert = (group: ExpressionTree): ExpressionTree => group.id === groupId ? { ...group, children: [...group.children, ruleId] } : { ...group, children: group.children.map(child => isExpressionTree(child) ? insert(child) : child) };
  return insert(withoutRule);
};
const addGroupToTree = (tree: ExpressionTree, groupId: string): ExpressionTree => {
  const group: ExpressionTree = { id: `group-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`, logic: "AND", children: [] };
  const insert = (current: ExpressionTree): ExpressionTree => current.id === groupId ? { ...current, children: [...current.children, group] } : { ...current, children: current.children.map(child => isExpressionTree(child) ? insert(child) : child) };
  return insert(tree);
};
const removeGroupFromTree = (tree: ExpressionTree, groupId: string): ExpressionTree => ({ ...tree, children: tree.children.flatMap(child => isExpressionTree(child) && child.id === groupId ? child.children : isExpressionTree(child) ? [removeGroupFromTree(child, groupId)] : [child]) });
const findGroupInTree = (tree: ExpressionTree, groupId: string): ExpressionTree | null => tree.id === groupId ? tree : tree.children.reduce<ExpressionTree | null>((found, child) => found ?? (isExpressionTree(child) ? findGroupInTree(child, groupId) : null), null);
const moveGroupToParent = (tree: ExpressionTree, groupId: string, parentId: string): ExpressionTree => {
  if (groupId === "root-group" || groupId === parentId) return tree;
  const moving = findGroupInTree(tree, groupId);
  if (!moving || findGroupInTree(moving, parentId)) return tree;
  const detach = (group: ExpressionTree): ExpressionTree => ({ ...group, children: group.children.filter(child => !isExpressionTree(child) || child.id !== groupId).map(child => isExpressionTree(child) ? detach(child) : child) });
  const withoutGroup = detach(tree);
  const insert = (group: ExpressionTree): ExpressionTree => group.id === parentId ? { ...group, children: [...group.children, moving] } : { ...group, children: group.children.map(child => isExpressionTree(child) ? insert(child) : child) };
  return insert(withoutGroup);
};
const setGroupLogic = (tree: ExpressionTree, groupId: string, logic: RuleDetail["logic"]): ExpressionTree => tree.id === groupId ? { ...tree, logic } : { ...tree, children: tree.children.map(child => isExpressionTree(child) ? setGroupLogic(child, groupId, logic) : child) };
const treeRuleIds = (tree: ExpressionTree): string[] => tree.children.flatMap(child => isExpressionTree(child) ? treeRuleIds(child) : [child]);
const treeGroups = (tree: ExpressionTree): ExpressionTree[] => [tree, ...tree.children.flatMap(child => isExpressionTree(child) ? treeGroups(child) : [])];
const storedExpressionFromTree = (tree: ExpressionTree, rules: Rule[], toStoredRules: (items: Rule[]) => Array<any>): Record<string, unknown> => {
  const ruleMap = new Map(toStoredRules(rules).map(rule => [rule.id, rule]));
  const serialize = (group: ExpressionTree): Record<string, unknown> => ({ id: group.id, logic: group.logic, enabled: true, children: group.children.map(child => isExpressionTree(child) ? serialize(child) : ruleMap.get(child)).filter(Boolean) });
  const serialized = serialize(tree);
  const missing = rules.filter(rule => !treeRuleIds(tree).includes(rule.id)).map(rule => ruleMap.get(rule.id)).filter(Boolean);
  return { ...serialized, children: [...(serialized.children as unknown[]), ...missing] };
};
const expressionTreeFromStored = (value: unknown, fallbackRules: Rule[]): ExpressionTree => {
  const parse = (node: any): ExpressionTree => ({ id: typeof node?.id === "string" ? node.id : `group-${Date.now()}`, logic: node?.logic === "OR" || node?.logic === "NOT" ? node.logic : "AND", children: Array.isArray(node?.children) ? node.children.map((child: any) => Array.isArray(child?.children) ? parse(child) : String(child?.id ?? "")).filter(Boolean) : [] });
  const tree = value && typeof value === "object" && Array.isArray((value as any).children) ? parse(value) : initialExpressionTree(fallbackRules);
  const known = new Set(treeRuleIds(tree));
  return { ...tree, id: "root-group", children: [...tree.children, ...fallbackRules.filter(rule => !known.has(rule.id)).map(rule => rule.id)] };
};

