function OperatorAccount() {
  const { user, logout } = useAuth();
  const operatorReason = user?.operatorReason === "admin_role" ? "관리자 역할" : user?.operatorReason === "owner_open_id" ? "소유자 계정" : user?.operatorReason === "configured_operator_email" ? "등록 운영자 이메일" : "운영자 권한 없음";
  const handleLogout = async () => {
    try {
      await logout();
      toast.success("운영자 로그아웃이 완료되었습니다.");
    } catch {
      toast.error("로그아웃을 완료하지 못했습니다. 다시 시도하세요.");
    }
  };
  if (!user) return <button onClick={() => startLogin()} className="ml-1 rounded-xl border border-amber-300/25 bg-amber-300/10 px-3 py-2 text-xs font-semibold text-amber-100 hover:bg-amber-300/15">운영자 로그인 필요</button>;
  return <div className="ml-1 flex items-center gap-2 rounded-xl border border-slate-800 bg-slate-900/50 py-1.5 pl-2 pr-3"><div className="flex h-6 w-6 items-center justify-center rounded-lg bg-gradient-to-br from-slate-600 to-slate-800 text-[10px] font-bold text-slate-200">O</div><div className="hidden min-w-0 sm:block"><p className="max-w-44 truncate text-xs font-semibold text-slate-300">{user.email ?? user.name ?? "로그인 계정"}</p><p className="mt-0.5 text-[10px] font-semibold text-teal-300/80">{user.isOperator ? `운영자 권한 확인됨 · ${operatorReason}` : operatorReason}</p><button onClick={() => void handleLogout()} className="mt-0.5 text-[10px] font-semibold text-slate-500 hover:text-teal-200">로그아웃</button></div></div>;
}

function OperatorAccessGate({ children }: { children: React.ReactNode }) {
  const { user, loading, refresh, logout } = useAuth();
  if (loading) return <div className="flex min-h-screen items-center justify-center bg-[#090e16] text-sm text-slate-400"><Loader2 className="mr-2 animate-spin" size={17}/>운영자 세션을 확인하는 중입니다.</div>;
  if (!user) return <div className="flex min-h-screen items-center justify-center bg-[#090e16] px-5 text-slate-100"><section className="w-full max-w-lg rounded-2xl border border-amber-300/20 bg-slate-900/70 p-7 text-center shadow-2xl"><LockKeyhole className="mx-auto mb-4 text-amber-300" size={28}/><h1 className="text-xl font-bold">운영자 로그인 세션이 없습니다.</h1><p className="mt-3 text-sm leading-relaxed text-slate-400">화면의 ‘운영자’ 표시는 권한 보증이 아닙니다. 서버 세션을 다시 연결한 뒤 일별 연구 프로그램을 저장하세요.</p><Button onClick={() => startLogin()} className="mt-6 bg-teal-300 text-slate-950 hover:bg-teal-200">운영자 로그인 다시 연결</Button></section></div>;
  if (!user.isOperator) return <div className="flex min-h-screen items-center justify-center bg-[#090e16] px-5 text-slate-100"><section className="w-full max-w-lg rounded-2xl border border-rose-300/20 bg-slate-900/70 p-7 text-center shadow-2xl"><ShieldCheck className="mx-auto mb-4 text-rose-300" size={28}/><h1 className="text-xl font-bold">현재 계정에는 운영자 권한이 없습니다.</h1><p className="mt-3 text-sm leading-relaxed text-slate-400">로그인 계정: {user.email ?? user.name ?? "확인 불가"}. 소유자 계정으로 다시 로그인한 뒤 권한을 새로고침하세요.</p><div className="mt-6 flex justify-center gap-3"><Button onClick={() => void refresh()} variant="outline" className="border-slate-700 bg-slate-900 text-slate-200 hover:bg-slate-800 hover:text-white">권한 다시 확인</Button><Button onClick={() => void logout().then(() => startLogin())} className="bg-teal-300 text-slate-950 hover:bg-teal-200">다른 계정으로 로그인</Button></div></section></div>;
  return <>{children}</>;
}

function StatCard({ label, value, sub, tone, icon: Icon }: { label: string; value: string; sub: string; tone: string; icon: typeof TrendingUp }) {
  return <div className="frosted-panel relative overflow-hidden rounded-2xl p-5"><div className={cn("absolute right-0 top-0 h-20 w-20 -translate-y-6 translate-x-6 rounded-full blur-2xl opacity-30", tone)} /><div className="mb-5 flex items-center justify-between"><p className="text-xs font-semibold text-slate-400">{label}</p><div className={cn("rounded-lg p-2", tone, "bg-opacity-15 text-white")}><Icon size={16} /></div></div><div className="font-mono text-2xl font-medium tracking-tight text-white">{value}</div><p className="mt-2 text-xs text-slate-500">{sub}</p></div>;
}

function LegacyDashboard({ setActive }: { setActive: (page: Page) => void }) {
  const broker = trpc.quant.brokerStatus.useQuery(undefined, { retry: false });
  const rankings = trpc.rankings.latest.useQuery(undefined, { retry: false, refetchInterval: 60_000 });
  const items = rankings.data?.items ?? [];
  const averageScore = items.length ? items.reduce((total, item) => total + Number(item.score), 0) / items.length : null;
  const refresh = () => rankings.refetch();
  return <div className="enter-soft"><PageHeader eyebrow="LIVE MARKET INTELLIGENCE" title="실데이터 조건 후보"><Badge className={cn("border px-2.5 py-1 text-[11px] font-semibold", broker.data?.fixedIpRegistered ? "border-teal-300/20 bg-teal-300/10 text-teal-200" : "border-amber-300/20 bg-amber-300/10 text-amber-200")}><span className={cn("mr-1.5 inline-block h-1.5 w-1.5 rounded-full", broker.data?.fixedIpRegistered ? "bg-teal-300" : "bg-amber-300")} />{broker.data?.fixedIpRegistered ? "운영 API 검증 대기" : "지정 IP 등록 대기"}</Badge><Button onClick={refresh} disabled={rankings.isFetching} variant="outline" className="border-slate-700 bg-slate-900/60 text-slate-200 hover:bg-slate-800 hover:text-white"><RefreshCw className={cn("mr-2", rankings.isFetching && "animate-spin")} size={15} />실데이터 갱신</Button></PageHeader><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="조건 충족 종목" value={items.length ? String(items.length) : "—"} sub={items.length ? "최신 실데이터 스냅샷" : "실데이터 스냅샷 없음"} tone="bg-teal-400" icon={Sparkles} /><StatCard label="평균 복합 점수" value={averageScore === null ? "—" : averageScore.toFixed(1)} sub="저장된 랭킹 기준" tone="bg-violet-400" icon={Activity} /><StatCard label="마지막 수집" value={rankings.data?.capturedAt ? new Date(rankings.data.capturedAt).toLocaleTimeString() : "—"} sub="키움 API 스냅샷" tone="bg-amber-400" icon={Clock3} /><StatCard label="운영 상태" value={broker.data?.hasCredentials ? "준비" : "대기"} sub={broker.data?.fixedIpRegistered ? "IP 등록됨" : "IP 등록 필요"} tone="bg-sky-400" icon={ShieldCheck} /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_0.85fr]"><section className="frosted-panel overflow-hidden rounded-2xl"><div className="flex items-center justify-between border-b border-slate-800/80 px-5 py-4"><div><h2 className="font-bold text-slate-100">조건 충족 랭킹</h2><p className="mt-1 text-xs text-slate-500">키움에서 수집·저장된 실제 스냅샷만 표시합니다.</p></div><button onClick={() => setActive("builder")} className="text-xs font-semibold text-teal-300 hover:text-teal-100">조건 편집 <ChevronRight className="inline" size={14} /></button></div>{items.length ? <div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left"><thead className="border-b border-slate-800/70 text-[10px] uppercase tracking-[0.14em] text-slate-500"><tr><th className="px-5 py-3">순위</th><th className="px-2 py-3">종목</th><th className="px-2 py-3 text-right">현재가</th><th className="px-2 py-3 text-right">등락률</th><th className="px-2 py-3 text-right">조건</th><th className="px-5 py-3 text-right">점수</th></tr></thead><tbody>{items.map((item, index) => <tr key={item.id} className="border-b border-slate-800/50 text-sm"><td className="px-5 py-3.5 font-mono text-xs text-slate-400">{index + 1}</td><td className="px-2 py-3.5"><button onClick={() => setActive("chart")} className="text-left"><div className="font-semibold text-slate-100">{item.name}</div><div className="mt-0.5 font-mono text-[10px] text-slate-500">{item.symbol}</div></button></td><td className="px-2 py-3.5 text-right font-mono text-xs text-slate-200">{item.price.toLocaleString()}</td><td className="px-2 py-3.5 text-right font-mono text-xs text-slate-300">{Number(item.changeRate).toFixed(2)}%</td><td className="px-2 py-3.5 text-right"><span className="rounded-full bg-teal-400/10 px-2 py-1 font-mono text-[10px] text-teal-200">{Array.isArray(item.matchedRulesJson) ? item.matchedRulesJson.length : 0}</span></td><td className="px-5 py-3.5 text-right font-mono text-white">{Number(item.score).toFixed(1)}</td></tr>)}</tbody></table></div> : <div className="flex min-h-72 flex-col items-center justify-center px-6 text-center"><CircleAlert className="mb-3 text-slate-600" size={24} /><p className="text-sm font-semibold text-slate-300">표시할 실제 랭킹 데이터가 없습니다.</p><p className="mt-2 max-w-sm text-xs leading-relaxed text-slate-500">지정 IP 등록과 OAuth 검증 뒤 키움 일봉·순위 데이터를 수집하면, 조건 평가를 통과한 실제 종목만 이 영역에 표시됩니다.</p></div>}</section><section className="frosted-panel rounded-2xl p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-slate-400">활성 조건식</p><h2 className="mt-1 font-bold text-slate-100">조건 빌더에서 관리</h2></div><button onClick={() => setActive("builder")} className="rounded-lg border border-slate-700 p-1.5 text-slate-400 hover:text-white"><MoreHorizontal size={16} /></button></div><div className="mt-6 space-y-3"><p className="text-xs leading-relaxed text-slate-500">지표·연산자·기간·기준값·논리 그룹을 상세 조건식에서 설정합니다. 실데이터 수집 전에는 성과·순위 값을 표시하지 않습니다.</p><Button onClick={() => setActive("builder")} className="w-full bg-teal-300 text-slate-950 hover:bg-teal-200">조건식 상세 편집 <ChevronRight className="ml-1" size={16} /></Button></div><div className="mt-5 rounded-xl border border-amber-300/15 bg-amber-300/[0.05] p-3.5"><div className="flex gap-2"><CircleAlert className="mt-0.5 shrink-0 text-amber-300" size={15} /><p className="text-[11px] leading-relaxed text-slate-400">자동매매 후보는 실데이터 조건 평가와 안전 한도·사용자 최종 확인을 모두 통과해야 합니다.</p></div></div></section></div></div>;
}

function Dashboard({ setActive }: { setActive: (page: Page) => void }) {
  const broker = trpc.quant.brokerStatus.useQuery(undefined, { retry: false });
  const rankings = trpc.rankings.latest.useQuery(undefined, { retry: false, refetchInterval: 60_000 });
  const items = rankings.data?.items ?? [];
  const access = presentKiwoomAccess(broker.data?.fixedIpRegistered);
  const oauth = presentOAuthStatus(broker.data?.oauth);
  const averageScore = items.length ? items.reduce((total, item) => total + Number(item.score), 0) / items.length : null;
  return <div className="enter-soft"><PageHeader eyebrow="RESEARCH WORKSPACE" title="조건식 리서치 홈"><Badge className={cn("border px-2.5 py-1 text-[11px] font-semibold", access.tone === "ready" ? "border-teal-300/20 bg-teal-300/10 text-teal-200" : "border-amber-300/20 bg-amber-300/10 text-amber-200")}><span className={cn("mr-1.5 inline-block h-1.5 w-1.5 rounded-full", access.tone === "ready" ? "bg-teal-300" : "bg-amber-300")}/>{access.label}</Badge><Button onClick={() => rankings.refetch()} disabled={rankings.isFetching} variant="outline" className="border-slate-700 bg-slate-900/60 text-slate-200 hover:bg-slate-800 hover:text-white"><RefreshCw className={cn("mr-2", rankings.isFetching && "animate-spin")} size={15}/>리서치 데이터 새로고침</Button></PageHeader><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="연구 후보 종목" value={items.length ? String(items.length) : "—"} sub={items.length ? "최신 실주가 스냅샷" : "준비된 데이터셋 없음"} tone="bg-teal-400" icon={Sparkles}/><StatCard label="평균 조건 점수" value={averageScore === null ? "—" : averageScore.toFixed(1)} sub="저장된 연구 조건식 기준" tone="bg-violet-400" icon={Activity}/><StatCard label="마지막 데이터 수집" value={rankings.data?.capturedAt ? new Date(rankings.data.capturedAt).toLocaleTimeString() : "—"} sub="실주가 원천 스냅샷" tone="bg-amber-400" icon={Clock3}/><StatCard label="데이터 연결" value={broker.data?.hasCredentials ? "준비" : "대기"} sub={access.label} tone="bg-sky-400" icon={ShieldCheck}/></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_0.85fr]"><section className="frosted-panel overflow-hidden rounded-2xl"><div className="flex items-center justify-between border-b border-slate-800/80 px-5 py-4"><div><h2 className="font-bold text-slate-100">최근 연구 후보 스냅샷</h2><p className="mt-1 text-xs text-slate-500">조건식·실주가 데이터셋에서 수집·저장된 후보만 표시합니다.</p></div><button onClick={() => setActive("builder")} className="text-xs font-semibold text-teal-300 hover:text-teal-100">조건식 연구 <ChevronRight className="inline" size={14}/></button></div>{items.length ? <div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left"><thead className="border-b border-slate-800/70 text-[10px] uppercase tracking-[0.14em] text-slate-500"><tr><th className="px-5 py-3">순위</th><th className="px-2 py-3">종목</th><th className="px-2 py-3 text-right">현재가</th><th className="px-2 py-3 text-right">등락률</th><th className="px-2 py-3 text-right">조건</th><th className="px-5 py-3 text-right">점수</th></tr></thead><tbody>{items.map((item, index) => <tr key={item.id} className="border-b border-slate-800/50 text-sm"><td className="px-5 py-3.5 font-mono text-xs text-slate-400">{index + 1}</td><td className="px-2 py-3.5"><button onClick={() => setActive("chart")} className="text-left"><div className="font-semibold text-slate-100">{item.name}</div><div className="mt-0.5 font-mono text-[10px] text-slate-500">{item.symbol}</div></button></td><td className="px-2 py-3.5 text-right font-mono text-xs text-slate-200">{item.price.toLocaleString()}</td><td className="px-2 py-3.5 text-right font-mono text-xs text-slate-300">{Number(item.changeRate).toFixed(2)}%</td><td className="px-2 py-3.5 text-right"><span className="rounded-full bg-teal-400/10 px-2 py-1 font-mono text-[10px] text-teal-200">{Array.isArray(item.matchedRulesJson) ? item.matchedRulesJson.length : 0}</span></td><td className="px-5 py-3.5 text-right font-mono text-white">{Number(item.score).toFixed(1)}</td></tr>)}</tbody></table></div> : <div className="flex min-h-72 flex-col items-center justify-center px-6 text-center"><CircleAlert className="mb-3 text-slate-600" size={24}/><p className="text-sm font-semibold text-slate-300">준비된 리서치 데이터가 없습니다.</p><p className="mt-2 max-w-sm text-xs leading-relaxed text-slate-500">{access.detail} OAuth 검증 뒤 키움 일봉·순위 데이터를 수집하면 조건식 연구를 위한 실제 후보가 표시됩니다.</p></div>}</section><section className="frosted-panel rounded-2xl p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-slate-400">현재 연구 조건식</p><h2 className="mt-1 font-bold text-slate-100">조건식 연구실에서 관리</h2></div><button onClick={() => setActive("builder")} className="rounded-lg border border-slate-700 p-1.5 text-slate-400 hover:text-white"><MoreHorizontal size={16}/></button></div><div className="mt-6 space-y-3"><p className="text-xs leading-relaxed text-slate-500">지표·연산자·기간·기준값·논리 그룹을 버전으로 저장합니다. 백테스트는 동일한 실주가 데이터셋과 가정을 고정해 반복 검증합니다.</p><Button onClick={() => setActive("builder")} className="w-full bg-teal-300 text-slate-950 hover:bg-teal-200">조건식 연구 시작 <ChevronRight className="ml-1" size={16}/></Button></div><div className="mt-5 rounded-xl border border-amber-300/15 bg-amber-300/[0.05] p-3.5"><div className="flex gap-2"><CircleAlert className="mt-0.5 shrink-0 text-amber-300" size={15}/><p className="text-[11px] leading-relaxed text-slate-400">OAuth 상태: {oauth.label}. 실거래 기능은 기본 잠금 상태이며, 조건식 연구와 백테스트 결과만으로 활성화되지 않습니다.</p></div></div></section></div></div>;
}

function RuleCard({ rule, onToggle, onRemove, onDragStart, onDrop, onDetailChange }: { rule: Rule; onToggle: () => void; onRemove: () => void; onDragStart: () => void; onDrop: () => void; onDetailChange: (detail: RuleDetail) => void }) {
  const color = rule.tone === "aqua" ? "border-teal-300/30 bg-teal-300/[0.045]" : rule.tone === "violet" ? "border-violet-300/30 bg-violet-300/[0.045]" : rule.tone === "amber" ? "border-amber-300/30 bg-amber-300/[0.045]" : "border-sky-300/30 bg-sky-300/[0.045]";
  const detail = rule.detail ?? { logic: "AND" as const, comparator: "이상" as const, period: rule.title.includes("고가") ? 11 : rule.title.includes("MACD") ? 3 : 5, threshold: rule.title.includes("거래대금") ? 500 : 20, unit: rule.title.includes("거래대금") ? "억원" as const : rule.title.includes("이동평균") ? "원" as const : "%" as const };
  const update = <K extends keyof RuleDetail>(key: K, value: RuleDetail[K]) => onDetailChange({ ...detail, [key]: value });
  const unitOptions = rule.title.includes("거래대금") ? ["억원", "원"] as const : rule.title.includes("이동평균") ? ["원"] as const : ["%"] as const;
  return <div draggable onDragStart={onDragStart} onDragOver={event => event.preventDefault()} onDrop={onDrop} className={cn("group rounded-xl border p-3.5 transition-all hover:-translate-y-0.5", color, !rule.enabled && "opacity-50")}><div className="flex items-center gap-3"><GripVertical className="cursor-grab text-slate-600" size={17} /><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><p className="truncate text-sm font-bold text-slate-100">{rule.title}</p><span className="rounded bg-slate-900/70 px-1.5 py-0.5 font-mono text-[9px] text-slate-400">+{rule.weight}</span></div><p className="mt-1 text-xs text-slate-500">{rule.subtitle}</p></div><Switch checked={rule.enabled} onCheckedChange={onToggle} aria-label={`${rule.title} 사용 여부`} /><button onClick={onRemove} className="hidden rounded p-1 text-slate-500 hover:bg-slate-900 hover:text-rose-300 group-hover:block"><X size={14} /></button></div><details className="mt-3 border-t border-slate-700/60 pt-2.5"><summary className="cursor-pointer text-[11px] font-semibold text-teal-200">상세 조건식 편집</summary><div className="mt-3 grid gap-2 sm:grid-cols-5"><label className="text-[10px] text-slate-500">논리<select value={detail.logic} onChange={event => update("logic", event.target.value as RuleDetail["logic"])} className="mt-1 h-8 w-full rounded border border-slate-700 bg-slate-950 px-1.5 text-xs text-slate-200"><option>AND</option><option>OR</option><option>NOT</option></select></label><label className="text-[10px] text-slate-500">비교<select value={detail.comparator} onChange={event => update("comparator", event.target.value as RuleDetail["comparator"])} className="mt-1 h-8 w-full rounded border border-slate-700 bg-slate-950 px-1.5 text-xs text-slate-200"><option>이상</option><option>초과</option><option>이하</option><option>미만</option><option>상향돌파</option><option>하향돌파</option></select></label><label className="text-[10px] text-slate-500">기간<Input type="number" min={1} value={detail.period} onChange={event => update("period", Number(event.target.value))} className="mt-1 h-8 border-slate-700 bg-slate-950 px-2 text-xs text-slate-100" /></label><label className="text-[10px] text-slate-500">기준값<Input type="number" min={0} value={detail.threshold} onChange={event => update("threshold", Number(event.target.value))} className="mt-1 h-8 border-slate-700 bg-slate-950 px-2 text-xs text-slate-100" /></label><label className="text-[10px] text-slate-500">단위<select value={detail.unit} onChange={event => update("unit", event.target.value as RuleDetail["unit"])} className="mt-1 h-8 w-full rounded border border-slate-700 bg-slate-950 px-1.5 text-xs text-slate-200">{unitOptions.map(unit => <option key={unit}>{unit}</option>)}</select></label></div><p className="mt-2 font-mono text-[10px] text-slate-500">{detail.logic} · 최근 {detail.period}일 · {detail.comparator} {detail.threshold.toLocaleString()}{detail.unit}</p></details></div>;
}

export function ResearchDashboard({ setActive }: { setActive: (page: Page) => void }) {
  return <MinuteResearchWorkspace setActive={setActive} />;
}

function ConditionFormulaPreview({ rules, rootLogic, onRootLogicChange }: { rules: Rule[]; rootLogic: RuleDetail["logic"]; onRootLogicChange: (logic: RuleDetail["logic"]) => void }) {
  return <div className="frosted-panel rounded-2xl p-5"><div className="flex items-center justify-between gap-3"><div><h2 className="font-bold text-white">조건식 상세 미리보기</h2><p className="mt-1 text-xs text-slate-500">저장되는 논리 구조와 규칙 파라미터입니다.</p></div><select value={rootLogic} onChange={event => onRootLogicChange(event.target.value as RuleDetail["logic"])} className="h-8 rounded border border-violet-300/30 bg-violet-300/10 px-2 text-[11px] font-semibold text-violet-100"><option>AND</option><option>OR</option><option>NOT</option></select></div><div className="mt-4 space-y-2">{rules.filter(rule => rule.enabled).map((rule, index) => { const detail = rule.detail ?? { logic: "AND", comparator: "이상", period: 5, threshold: 0, unit: "%" }; return <div key={rule.id} className="rounded-xl border border-slate-800 bg-slate-950/35 p-3"><div className="flex items-center gap-2"><span className="font-mono text-[10px] text-teal-300">{index === 0 ? `IF (${rootLogic})` : detail.logic}</span><span className="min-w-0 flex-1 truncate text-xs font-semibold text-slate-200">{rule.title}</span><span className="font-mono text-[10px] text-slate-500">+{rule.weight}</span></div><p className="mt-1.5 font-mono text-[11px] text-slate-400">최근 {detail.period}일 · {detail.comparator} · {detail.threshold.toLocaleString()}{detail.unit}</p></div>})}{rules.every(rule => !rule.enabled) && <p className="py-3 text-center text-xs text-slate-500">활성화된 조건이 없습니다.</p>}</div></div>;
}

function NestedExpressionEditor({ tree, rules, onChange }: { tree: ExpressionTree; rules: Rule[]; onChange: (tree: ExpressionTree) => void }) {
  const ruleName = (id: string) => rules.find(rule => rule.id === id)?.title ?? id;
  const groups = treeGroups(tree);
  const renderGroup = (group: ExpressionTree, depth = 0): React.ReactNode => <div key={group.id} className={cn("rounded-xl border border-violet-300/15 bg-violet-300/[0.035] p-3", depth > 0 && "ml-3 border-slate-700 bg-slate-950/35")}><div className="flex flex-wrap items-center gap-2"><Badge className="border-violet-300/20 bg-violet-300/10 text-[10px] text-violet-100">{depth ? "중첩 그룹" : "루트 그룹"}</Badge><select aria-label={`${group.id} 논리`} value={group.logic} onChange={event => onChange(setGroupLogic(tree, group.id, event.target.value as RuleDetail["logic"]))} className="h-7 rounded border border-violet-300/30 bg-slate-950 px-2 text-[11px] font-semibold text-violet-100"><option>AND</option><option>OR</option><option>NOT</option></select><button onClick={() => onChange(addGroupToTree(tree, group.id))} className="rounded border border-slate-700 px-2 py-1 text-[10px] font-semibold text-slate-300 hover:border-violet-300/50 hover:text-violet-100">하위 그룹 추가</button>{group.id !== "root-group" && <button onClick={() => onChange(removeGroupFromTree(tree, group.id))} className="rounded border border-rose-300/20 px-2 py-1 text-[10px] font-semibold text-rose-200 hover:bg-rose-300/10">그룹 해제</button>}<select aria-label={`${group.id} 규칙 이동`} defaultValue="" onChange={event => { if (event.target.value) { onChange(moveRuleToGroup(tree, group.id, event.target.value)); event.currentTarget.value = ""; } }} className="ml-auto h-7 max-w-40 rounded border border-slate-700 bg-slate-950 px-2 text-[10px] text-slate-300"><option value="">규칙 이동…</option>{rules.map(rule => <option key={rule.id} value={rule.id}>{rule.title}</option>)}</select></div><div className="mt-2 space-y-2">{group.children.map(child => isExpressionTree(child) ? renderGroup(child, depth + 1) : <div key={child} className="flex items-center gap-2 rounded-lg border border-slate-800 bg-slate-950/40 px-2.5 py-2"><span className="h-1.5 w-1.5 rounded-full bg-teal-300"/><span className="min-w-0 flex-1 truncate text-[11px] text-slate-200">{ruleName(child)}</span><button onClick={() => onChange(moveRuleToGroup(tree, "root-group", child))} className="text-[10px] font-semibold text-slate-500 hover:text-teal-200">루트로 이동</button></div>)}</div></div>;
  return <section className="frosted-panel rounded-2xl p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-bold text-white">중첩 논리 그룹</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">규칙·그룹을 다른 부모 그룹으로 이동하고 하위 AND·OR·NOT 그룹을 중첩해 저장합니다.</p></div><SlidersHorizontal className="text-violet-300" size={19}/></div><div className="mt-4">{renderGroup(tree)}</div>{groups.length > 1 && <div className="mt-3 border-t border-slate-800 pt-3"><p className="mb-2 text-[10px] font-semibold uppercase tracking-wider text-slate-500">그룹 부모 이동</p><div className="space-y-2">{groups.filter(group => group.id !== "root-group").map(group => <label key={group.id} className="flex items-center justify-between gap-3 rounded-lg border border-slate-800 bg-slate-950/35 px-2.5 py-2 text-[11px] text-slate-300"><span className="font-mono">{group.logic} · {group.id.slice(-6)}</span><select aria-label={`${group.id} 부모 이동`} defaultValue="" onChange={event => { if (event.target.value) { onChange(moveGroupToParent(tree, group.id, event.target.value)); event.currentTarget.value = ""; } }} className="h-7 rounded border border-slate-700 bg-slate-950 px-2 text-[10px] text-slate-200"><option value="">이동할 부모…</option>{groups.filter(target => target.id !== group.id).map(target => <option key={target.id} value={target.id}>{target.id === "root-group" ? "루트 그룹" : `${target.logic} 그룹 ${target.id.slice(-4)}`}</option>)}</select></label>)}</div></div>}</section>;
}

function LiveRankingPanel({ presetId, presetName }: { presetId: number | null; presetName?: string }) {
  const utils = trpc.useUtils();
  const [universeText, setUniverseText] = useState("");
  const refresh = trpc.rankings.refresh.useMutation({
    onSuccess: result => { utils.rankings.latest.invalidate(); toast.success(result.source === "ka10081_local_snapshot" ? `${result.collectedSymbols.length}개 종목을 로컬 ka10081 불변 스냅샷 #${result.snapshotDatasetIds.join(", ")}으로 평가했습니다.` : `${result.collectedSymbols.length}개 종목의 키움 실제 일봉 평가를 완료했습니다.`); },
    onError: error => toast.error(error.message),
  });
  const symbols = Array.from(new Set(universeText.split(/[\s,]+/).map(value => value.trim()).filter(value => /^\d{6}$/.test(value))));
  const run = () => {
    if (!presetId) { toast.error("저장된 프리셋을 먼저 선택하세요."); return; }
    if (!symbols.length) { toast.error("6자리 종목코드를 하나 이상 입력하세요."); return; }
    refresh.mutate({ presetId, universe: symbols.map(symbol => ({ symbol })), maxPagesPerSymbol: 3 });
  };
  return <div className="frosted-panel rounded-2xl p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-bold text-white">실데이터 랭킹 갱신</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">입력한 유니버스의 키움 일봉만 수집해 선택 프리셋으로 평가합니다. 종목명은 데이터 검증 전까지 종목코드로 표시됩니다.</p></div><RefreshCw className={cn("mt-0.5 text-teal-300", refresh.isPending && "animate-spin")} size={19}/></div><label className="mt-5 block text-xs text-slate-400">종목코드 유니버스 <span className="text-slate-600">(공백 또는 쉼표로 구분, 최대 20개)</span><Textarea value={universeText} onChange={event => setUniverseText(event.target.value.replace(/[^0-9,\s]/g, ""))} placeholder="예: 005930, 000660, 035420" className="mt-2 min-h-20 border-slate-700 bg-slate-900 font-mono text-xs text-slate-100" /></label><div className="mt-3 flex items-center justify-between text-[11px] text-slate-500"><span>{presetName ? `선택 프리셋: ${presetName}` : "선택된 저장 프리셋 없음"}</span><span>{symbols.length}/20 종목</span></div><Button onClick={run} disabled={refresh.isPending || !presetId || !symbols.length} className="mt-4 w-full bg-teal-300 text-slate-950 hover:bg-teal-200"><Play className="mr-2" size={15}/>{refresh.isPending ? "실데이터 평가 중" : "실데이터 랭킹 갱신"}</Button>{refresh.data && <div className="mt-4 rounded-xl border border-slate-800 bg-slate-950/35 p-3"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-slate-200">이번 평가 결과</p><span className="font-mono text-[10px] text-slate-500">{refresh.data.collectedSymbols.length}개 수집</span></div>{refresh.data.ranked.length ? <div className="mt-3 space-y-2">{refresh.data.ranked.slice(0, 5).map(item => <div key={item.symbol} className="flex items-center justify-between text-xs"><span className="font-mono text-slate-300">#{item.rank} · {item.symbol}</span><span className="font-mono text-teal-200">{item.score.toFixed(1)}점</span></div>)}</div> : <p className="mt-2 text-xs text-slate-500">조건을 충족한 종목이 없습니다.</p>}{refresh.data.failedSymbols.length > 0 && <p className="mt-3 text-[11px] text-amber-200">수집 실패 {refresh.data.failedSymbols.length}개 — 키움 연결 상태를 확인하세요.</p>}</div>}</div>;
}

export function TurnoverRankingPanel() {
  const ranking = trpc.rankings.turnover.useQuery({ market: "000", exchange: "KRX", includeManagedStocks: false }, { enabled: false, retry: false });
  const items = ranking.data?.items ?? [];
  return <section className="frosted-panel rounded-2xl p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-bold text-white">시장 거래대금 순위</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">키움 공식 거래대금 상위(`ka10032`)를 요청 시점에만 조회합니다. 인증 대기 중에는 예시 순위를 표시하지 않습니다.</p></div><Activity className={cn("mt-0.5 text-amber-300", ranking.isFetching && "animate-pulse")} size={19}/></div><Button onClick={() => ranking.refetch()} disabled={ranking.isFetching} variant="outline" className="mt-4 w-full border-amber-300/20 bg-amber-300/[0.06] text-amber-100 hover:bg-amber-300/[0.12] hover:text-amber-50"><RefreshCw className={cn("mr-2", ranking.isFetching && "animate-spin")} size={15}/>{ranking.isFetching ? "거래대금 순위 조회 중" : "공식 거래대금 순위 조회"}</Button>{ranking.error ? <div className="mt-4 rounded-xl border border-amber-300/20 bg-amber-300/[0.06] p-3 text-xs text-amber-100"><p className="font-semibold">실데이터 순위를 불러오지 못했습니다.</p><p className="mt-1 leading-relaxed opacity-80">{ranking.error.message}</p><p className="mt-2 text-[11px] text-slate-400">지정 단말 OAuth 인증이 정상화되면 동일 버튼으로 실제 결과를 조회할 수 있습니다.</p></div> : items.length ? <div className="mt-4 overflow-x-auto"><table className="w-full min-w-[450px] text-left text-xs"><thead className="border-b border-slate-800 text-[10px] uppercase tracking-wider text-slate-500"><tr><th className="px-2 py-2">순위</th><th className="px-2 py-2">종목</th><th className="px-2 py-2 text-right">현재가</th><th className="px-2 py-2 text-right">등락률</th><th className="px-2 py-2 text-right">거래대금</th></tr></thead><tbody>{items.slice(0, 10).map(item => <tr key={`${item.symbol}-${item.rank}`} className="border-b border-slate-800/60"><td className="px-2 py-2.5 font-mono text-slate-400">{item.rank}</td><td className="px-2 py-2.5"><p className="font-semibold text-slate-200">{item.name || item.symbol}</p><p className="font-mono text-[10px] text-slate-500">{item.symbol}</p></td><td className="px-2 py-2.5 text-right font-mono text-slate-200">{item.price.toLocaleString()}</td><td className={cn("px-2 py-2.5 text-right font-mono", item.changeRate > 0 ? "text-rose-200" : item.changeRate < 0 ? "text-sky-200" : "text-slate-300")}>{item.changeRate.toFixed(2)}%</td><td className="px-2 py-2.5 text-right font-mono text-amber-100">{(Math.round(item.turnover / 10_000_000) / 10).toFixed(1)}억</td></tr>)}</tbody></table></div> : <div className="mt-4 rounded-xl border border-dashed border-slate-700 p-4 text-center text-xs leading-relaxed text-slate-500">조회 버튼을 누르면 키움 OAuth 인증 후 실제 거래대금 순위만 표시합니다.</div>}</section>;
}

export function HtsConditionSourcePanel() {
  return <section className="frosted-panel rounded-2xl border border-violet-300/15 p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-bold text-white">HTS 조건식 · 데이터 출처</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">영웅문4에 저장한 조건식은 OAuth 인증 후 현재 후보 종목을 조회하는 용도입니다. 키움 로그인 ID·비밀번호는 입력하거나 저장하지 않습니다.</p></div><Sparkles className="mt-0.5 text-violet-300" size={19}/></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><div className="rounded-xl border border-violet-300/15 bg-violet-300/[0.04] p-3"><p className="text-xs font-semibold text-violet-100">HTS 현재 후보 · 워크포워드</p><p className="mt-1.5 text-[11px] leading-relaxed text-slate-400">OAuth 읽기 전용 검증이 성공한 뒤에만 조건식 번호와 현재 충족 종목을 시각별 스냅샷으로 기록합니다. 현재는 후보 데이터가 없으면 수집 대기 상태만 표시합니다.</p><p className="mt-2 font-mono text-[10px] text-violet-200">CURRENT SNAPSHOT ONLY</p></div><div className="rounded-xl border border-teal-300/15 bg-teal-300/[0.04] p-3"><p className="text-xs font-semibold text-teal-100">앱 조건 빌더 · 과거 백테스트</p><p className="mt-1.5 text-[11px] leading-relaxed text-slate-400">동일 논리로 재구성한 MACD·이동평균·고가·거래대금 규칙과 고정된 실제 일봉만 사용해 과거 시점별로 평가합니다.</p><p className="mt-2 font-mono text-[10px] text-teal-200">HISTORICAL REPLAY</p></div></div><div className="mt-4 flex gap-2 rounded-xl border border-amber-300/15 bg-amber-300/[0.05] p-3"><CircleAlert className="mt-0.5 shrink-0 text-amber-300" size={15}/><p className="text-[11px] leading-relaxed text-slate-400">HTS 조건검색의 현재 결과를 과거 조건 충족 이력으로 바꾸어 백테스트하지 않습니다. 지정 단말 OAuth 인증이 정상화되면 목록 조회와 현재 후보 수집만 활성화됩니다.</p></div></section>;
}

export function RankingAutomationPanel({ presetId, presetName }: { presetId: number | null; presetName?: string }) {
  const utils = trpc.useUtils();
  const profile = trpc.rankingRefresh.get.useQuery(undefined, { retry: false });
  const [universeText, setUniverseText] = useState("");
  const [cron, setCron] = useState("0 */15 * * * *");
  useEffect(() => { if (profile.data) { setUniverseText((profile.data.universeJson as Array<{ symbol: string }>).map(item => item.symbol).join(", ")); setCron(profile.data.cronExpression); } }, [profile.data]);
  const save = trpc.rankingRefresh.save.useMutation({ onSuccess: () => { utils.rankingRefresh.get.invalidate(); toast.success("랭킹 자동 갱신 설정을 저장했습니다."); }, onError: error => toast.error(error.message) });
  const effectivePresetId = presetId ?? profile.data?.presetId ?? null;
  const symbols = Array.from(new Set(universeText.split(/[\s,]+/).map(value => value.trim()).filter(value => /^\d{6}$/.test(value))));
  const submit = (enabled: boolean) => {
    if (!effectivePresetId) { toast.error("저장된 프리셋을 먼저 선택하세요."); return; }
    if (!symbols.length) { toast.error("6자리 종목코드를 하나 이상 입력하세요."); return; }
    save.mutate({ presetId: effectivePresetId, universe: symbols.map(symbol => ({ symbol })), maxPagesPerSymbol: 3, cron, enabled });
  };
  const statusTone = profile.data?.status === "ready" ? "text-teal-200" : profile.data?.status === "error" ? "text-rose-300" : "text-amber-200";
  return <div className="frosted-panel rounded-2xl p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-bold text-white">랭킹 자동 갱신</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">키움 접근 인증이 확인된 뒤에만 저장된 유니버스와 프리셋으로 실행됩니다. 주기는 UTC 6필드 형식입니다.</p></div><Clock3 className="mt-0.5 text-violet-300" size={19}/></div><div className="mt-5 grid gap-3"><label className="text-xs text-slate-400">종목코드 유니버스<Textarea value={universeText} onChange={event => setUniverseText(event.target.value.replace(/[^0-9,\s]/g, ""))} placeholder="예: 005930, 000660" className="mt-2 min-h-18 border-slate-700 bg-slate-900 font-mono text-xs text-slate-100"/></label><label className="text-xs text-slate-400">UTC 실행 주기<Input value={cron} onChange={event => setCron(event.target.value)} placeholder="0 */15 * * * *" className="mt-2 border-slate-700 bg-slate-900 font-mono text-xs text-slate-100"/></label></div><div className="mt-3 flex items-center justify-between text-[11px] text-slate-500"><span>{presetName ?? (profile.data ? `저장 프리셋 #${profile.data.presetId}` : "선택된 저장 프리셋 없음")}</span><span>{symbols.length}/20 종목</span></div>{profile.data && <div className="mt-4 rounded-xl border border-slate-800 bg-slate-950/35 p-3"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-slate-200">예약 작업 상태</p><span className={cn("text-xs font-semibold", statusTone)}>{profile.data.status}</span></div><p className="mt-1.5 text-[11px] text-slate-500">최근 완료: {profile.data.lastCompletedAt ? new Date(profile.data.lastCompletedAt).toLocaleString() : "없음"}</p>{profile.data.lastError && <p className="mt-2 text-[11px] text-amber-200">{profile.data.lastError}</p>}</div>}<div className="mt-4 flex gap-2"><Button onClick={() => submit(true)} disabled={save.isPending || !effectivePresetId || !symbols.length} className="flex-1 bg-violet-300 text-slate-950 hover:bg-violet-200"><Clock3 className="mr-2" size={15}/>{save.isPending ? "저장 중" : "자동 갱신 저장"}</Button><Button onClick={() => submit(false)} disabled={save.isPending || !effectivePresetId || !symbols.length} variant="outline" className="border-slate-700 text-slate-300 hover:bg-slate-800">중지</Button></div></div>;
}

function ExpressionOutline({ node, depth = 0 }: { node: any; depth?: number }) {
  if (!node || typeof node !== "object") return <p className="text-xs text-slate-500">저장된 논리 그룹이 없습니다. 활성 규칙은 기본 AND로 평가됩니다.</p>;
  if (!Array.isArray(node.children)) return null;
  return <div className="space-y-1.5" style={{ marginLeft: depth ? `${Math.min(depth, 3) * 12}px` : 0 }}><div className="flex items-center gap-2"><Badge className="border-violet-300/20 bg-violet-300/10 text-[10px] text-violet-200">{node.logic}</Badge><span className="text-[11px] text-slate-400">논리 그룹</span></div>{node.children.map((child: any) => Array.isArray(child.children) ? <ExpressionOutline key={child.id} node={child} depth={depth + 1}/> : <div key={child.id} className="flex items-center gap-2 pl-2 text-[11px] text-slate-300"><span className={child.enabled ? "h-1.5 w-1.5 rounded-full bg-teal-300" : "h-1.5 w-1.5 rounded-full bg-slate-600"}/><span>{child.type}</span><span className="text-slate-500">{String(child.config?.comparator ?? "이상")} · 가중치 {child.weight}</span></div>)}</div>;
}

export function PresetEvidencePanel({ presetId, presetName }: { presetId: number | null; presetName?: string }) {
  const [symbol, setSymbol] = useState("005930");
  const detail = trpc.presets.detail.useQuery({ id: presetId ?? 0 }, { enabled: Boolean(presetId), retry: false });
  const evidence = trpc.quant.evaluatePreset.useQuery({ presetId: presetId ?? 0, symbol, maxPages: 3 }, { enabled: false, retry: false });
  const rules = Array.isArray(detail.data?.rulesJson) ? detail.data.rulesJson as Array<any> : [];
  const canEvaluate = Boolean(presetId) && /^\d{6}$/.test(symbol);
  const noData = evidence.error?.message.startsWith("실데이터 없음:");
  return <section className="frosted-panel rounded-2xl p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-bold text-white">조건식 상세 · 평가 근거</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">저장된 규칙, 비교 연산과 실제 일봉의 실측값을 분리해 표시합니다.</p></div><Activity className="mt-0.5 text-teal-300" size={19}/></div>{detail.error && <div className="mt-4 rounded-xl border border-rose-300/20 bg-rose-300/[0.06] p-3 text-xs text-rose-200"><p className="font-semibold">프리셋 상세를 불러오지 못했습니다.</p><p className="mt-1 opacity-75">{detail.error.message}</p><button onClick={() => detail.refetch()} className="mt-2 font-semibold underline underline-offset-2">다시 시도</button></div>}{!presetId ? <div className="mt-5 rounded-xl border border-dashed border-slate-700 p-4 text-center text-xs text-slate-500">상세 조회할 저장 프리셋을 선택하세요.</div> : <><div className="mt-5 rounded-xl border border-slate-800 bg-slate-950/35 p-4"><div className="flex items-center justify-between gap-3"><p className="text-sm font-semibold text-slate-100">{presetName ?? detail.data?.name ?? "프리셋 불러오는 중"}</p><span className="font-mono text-[10px] text-slate-500">#{presetId}</span></div><div className="mt-3 space-y-2">{rules.map(rule => <div key={rule.id} className="rounded-lg border border-slate-800/80 bg-slate-900/40 p-2.5"><div className="flex items-center justify-between gap-2"><span className="text-xs font-semibold text-slate-200">{rule.type}</span><span className={rule.enabled ? "text-[10px] text-teal-200" : "text-[10px] text-slate-500"}>{rule.enabled ? "활성" : "비활성"} · {rule.weight}점</span></div><p className="mt-1 font-mono text-[10px] leading-relaxed text-slate-500">{Object.entries(rule.config ?? {}).map(([key, value]) => `${key}=${value}`).join(" · ")}</p></div>)}</div><div className="mt-4 border-t border-slate-800 pt-3"><p className="mb-2 text-[10px] font-semibold uppercase tracking-wider text-slate-500">저장된 논리 구조</p><ExpressionOutline node={detail.data?.scoringJson}/></div></div><div className="mt-4 flex gap-2"><Input value={symbol} onChange={event => setSymbol(event.target.value.replace(/\D/g, "").slice(0, 6))} placeholder="6자리 종목코드" className="border-slate-700 bg-slate-900 font-mono text-xs text-slate-100"/><Button onClick={() => evidence.refetch()} disabled={!canEvaluate || evidence.isFetching} className="shrink-0 bg-teal-300 text-slate-950 hover:bg-teal-200">{evidence.isFetching ? <Loader2 className="animate-spin" size={15}/> : "실데이터 평가"}</Button></div>{evidence.error ? <div className={cn("mt-4 rounded-xl border p-3 text-xs", noData ? "border-amber-300/20 bg-amber-300/[0.06] text-amber-200" : "border-rose-300/20 bg-rose-300/[0.06] text-rose-200")}><p className="font-semibold">{noData ? "수집된 실데이터 일봉이 없습니다." : "실데이터 평가를 완료하지 못했습니다."}</p><p className="mt-1 opacity-75">{evidence.error.message}</p></div> : evidence.data ? <div className="mt-4 rounded-xl border border-slate-800 bg-slate-950/35 p-4"><div className="flex items-center justify-between"><div><p className="text-xs font-semibold text-slate-200">{evidence.data.symbol} · {evidence.data.latestDate ?? "일자 없음"}</p><p className="mt-1 text-[10px] text-slate-500">{evidence.data.barCount}개 일봉 · {evidence.data.source}</p></div><Badge className={evidence.data.result.eligible ? "border-teal-300/20 bg-teal-300/10 text-teal-200" : "border-slate-700 bg-slate-800 text-slate-300"}>{evidence.data.result.eligible ? "조건 충족" : "조건 미충족"} · {evidence.data.result.score.toFixed(1)}점</Badge></div><div className="mt-3 space-y-2">{evidence.data.result.evaluations.map(item => <div key={item.ruleId} className="flex items-start justify-between gap-3 rounded-lg border border-slate-800/80 p-2.5"><div className="min-w-0"><p className="text-[11px] font-semibold text-slate-200">{item.detail}</p><p className="mt-1 font-mono text-[10px] text-slate-500">실측 {item.actual ?? "N/A"} · 기준 {item.expected ?? "N/A"} · {item.comparator ?? "비교 없음"}</p></div><span className={item.matched ? "shrink-0 text-[10px] font-semibold text-teal-200" : "shrink-0 text-[10px] font-semibold text-slate-500"}>{item.matched ? "충족" : "미충족"}</span></div>)}</div></div> : <div className="mt-4 rounded-xl border border-dashed border-slate-700 p-4 text-center text-xs text-slate-500">종목코드를 입력하고 실데이터 평가를 실행하면 조건별 근거가 표시됩니다. 키움 연결이 미검증이면 오류 상태만 표시됩니다.</div>}</>}</section>;
}

export function Builder() {
  const [rules, setRules] = useState(initialRules); const [expressionTree, setExpressionTree] = useState<ExpressionTree>(() => initialExpressionTree(initialRules)); const [dragged, setDragged] = useState<string | null>(null); const [preset, setPreset] = useState("momentum"); const [selectedPresetId, setSelectedPresetId] = useState<number | null>(null); const [rootLogic, setRootLogic] = useState<RuleDetail["logic"]>("AND");
  const utils = trpc.useUtils();
  const persistedPresets = trpc.presets.list.useQuery(undefined, { retry: false });
  const rankingAutomation = trpc.rankingRefresh.get.useQuery(undefined, { retry: false });
  const savePresetMutation = trpc.presets.save.useMutation({ onSuccess: result => { setSelectedPresetId(result.id); utils.presets.list.invalidate(); toast.success("프리셋을 안전하게 저장했습니다."); }, onError: error => toast.error(error.message) });
  const removePresetMutation = trpc.presets.remove.useMutation({ onSuccess: (_result, variables) => { if (selectedPresetId === variables.id) { setSelectedPresetId(null); setPreset("momentum"); } utils.presets.list.invalidate(); toast.success("프리셋을 삭제했습니다."); }, onError: error => toast.error(error.message) });
  const configForRule = (item: Rule): Record<string, string | number | boolean> => {
    const detail = item.detail ?? { logic: "AND", comparator: "이상", period: 5, threshold: item.title.includes("거래대금") ? 500 : 20, unit: item.title.includes("거래대금") ? "억원" : item.title.includes("이동평균") ? "원" : "%" };
    const common = { logic: detail.logic, comparator: detail.comparator };
    if (item.title.includes("MACD")) return { ...common, lookback: detail.period };
    if (item.title.includes("이동평균")) return { ...common, periods: String(detail.period), unit: "원" };
    if (item.title.includes("고가")) return { ...common, days: detail.period, minPercent: detail.threshold };
    return { ...common, days: detail.period, threshold: detail.unit === "억원" ? detail.threshold * 100_000_000 : detail.threshold };
  };
  const toStoredRules = (items: Rule[]) => items.map(item => ({
    id: item.id,
    type: item.title.includes("MACD") ? "macd_rising" as const : item.title.includes("이동평균") ? "ma_position" as const : item.title.includes("고가") ? "high_return" as const : "turnover" as const,
    enabled: item.enabled,
    weight: item.weight,
    config: configForRule(item),
  }));
  const toExpression = (items: Rule[]) => storedExpressionFromTree({ ...expressionTree, logic: rootLogic }, items, toStoredRules);
  const savePreset = () => {
    const selected = persistedPresets.data?.find(item => item.id === selectedPresetId);
    const fallbackName = preset === "momentum" ? "모멘텀 돌파 v2" : preset === "swing" ? "스윙 추세 추종" : "거래대금 집중";
    savePresetMutation.mutate({ id: selected?.id, name: selected?.name ?? fallbackName, description: "조건 빌더에서 저장한 전략", rules: toStoredRules(rules), expression: toExpression(rules), isActive: true });
  };
  const loadPreset = (item: { id: number; name: string; rulesJson: unknown; scoringJson?: unknown }) => {
    if (!Array.isArray(item.rulesJson)) return;
    if (item.scoringJson && typeof item.scoringJson === "object" && "logic" in item.scoringJson) {
      const logic = (item.scoringJson as { logic?: string }).logic;
      setRootLogic(logic === "OR" || logic === "NOT" ? logic : "AND");
    }
    setExpressionTree(expressionTreeFromStored(item.scoringJson, item.rulesJson.map((rule, index) => ({ id: String((rule as { id?: string }).id ?? `saved-${index}`) } as Rule))));
    const tone: Rule["tone"][] = ["aqua", "violet", "amber", "blue"];
    setRules(item.rulesJson.map((rule, index) => {
      const saved = rule as { id?: string; type?: string; enabled?: boolean; weight?: number; config?: Record<string, string | number | boolean> };
      const title = saved.type === "macd_rising" ? "MACD 오실레이터 우상향" : saved.type === "ma_position" ? "이동평균선 정배열" : saved.type === "high_return" ? "최근 11일 고가 등락률" : "거래대금 유입";
      const config = saved.config ?? {};
      const period = typeof config.days === "number" ? config.days : typeof config.lookback === "number" ? config.lookback : 5;
      const threshold = typeof config.minPercent === "number" ? config.minPercent : typeof config.threshold === "number" ? (config.unit === "억원" ? config.threshold / 100_000_000 : config.threshold) : 0;
      return { id: saved.id ?? `saved-${index}`, title, subtitle: "저장된 프리셋 조건", tone: tone[index % tone.length], enabled: saved.enabled ?? true, weight: saved.weight ?? 10, detail: { logic: config.logic === "OR" || config.logic === "NOT" ? config.logic : "AND", comparator: ["초과", "이하", "미만", "상향돌파", "하향돌파"].includes(String(config.comparator)) ? String(config.comparator) as RuleDetail["comparator"] : "이상", period, threshold, unit: config.unit === "원" || config.unit === "억원" ? config.unit : "%" } };
    }));
    setSelectedPresetId(item.id);
    toast.message(`${item.name} 프리셋을 불러왔습니다.`);
  };
  useEffect(() => { const profile = rankingAutomation.data; const savedPreset = persistedPresets.data?.find(item => item.id === profile?.presetId); if (profile && !selectedPresetId && savedPreset) loadPreset(savedPreset); }, [rankingAutomation.data, persistedPresets.data, selectedPresetId]);
  const reorder = (target: string) => { if (!dragged || dragged === target) return; setRules(items => { const from = items.findIndex(item => item.id === dragged); const to = items.findIndex(item => item.id === target); const copy = [...items]; const [moved] = copy.splice(from, 1); copy.splice(to, 0, moved); return copy; }); setDragged(null); };
  const addRule = () => setRules(items => [...items, { id: `turnover-${Date.now()}`, title: "당일 거래량 급증", subtitle: "20일 평균 대비 250% 이상", tone: "blue", enabled: true, weight: 15 }]);
  return <div className="enter-soft"><PageHeader eyebrow="STRATEGY WORKBENCH" title="기술지표 조건 빌더"><Select value={preset} onValueChange={value => { setPreset(value); setSelectedPresetId(null); }}><SelectTrigger className="h-10 w-[176px] border-slate-700 bg-slate-900 text-slate-100"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="momentum">모멘텀 돌파 v2</SelectItem><SelectItem value="swing">스윙 추세 추종</SelectItem><SelectItem value="volume">거래대금 집중</SelectItem></SelectContent></Select><Button onClick={savePreset} disabled={savePresetMutation.isPending} className="bg-teal-300 text-slate-950 hover:bg-teal-200"><Save className="mr-2" size={15} />{savePresetMutation.isPending ? "저장 중" : "저장"}</Button></PageHeader>
    <div className="grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><section className="frosted-panel rounded-2xl p-5"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-bold text-white">조건 조합</h2><p className="mt-1 text-xs text-slate-500">카드를 끌어 우선순위를 변경할 수 있습니다.</p></div><span className="font-mono text-xs text-teal-200">{rules.filter(rule => rule.enabled).length} ACTIVE</span></div><div className="space-y-2.5">{rules.map(rule => <RuleCard key={rule.id} rule={rule} onDragStart={() => setDragged(rule.id)} onDrop={() => reorder(rule.id)} onToggle={() => setRules(items => items.map(item => item.id === rule.id ? { ...item, enabled: !item.enabled } : item))} onRemove={() => setRules(items => items.filter(item => item.id !== rule.id))} onDetailChange={detail => setRules(items => items.map(item => item.id === rule.id ? { ...item, detail } : item))} />)}</div><button onClick={addRule} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl border border-dashed border-slate-700 py-3 text-xs font-semibold text-slate-400 transition-colors hover:border-teal-300/50 hover:bg-teal-300/[0.04] hover:text-teal-200"><Plus size={15} />조건 추가</button></section>
      <section className="space-y-5"><div className="frosted-panel rounded-2xl p-5"><div className="flex items-center justify-between"><h2 className="font-bold text-white">점수 규칙</h2><span className="text-xs text-slate-500">총점 100</span></div><div className="mt-5 space-y-5">{rules.filter(rule => rule.enabled).map(rule => <div key={rule.id}><div className="mb-2 flex items-center justify-between text-xs"><span className="text-slate-300">{rule.title}</span><span className="font-mono text-teal-200">{rule.weight}점</span></div><input aria-label={`${rule.title} 가중치`} type="range" min="5" max="50" value={rule.weight} onChange={event => setRules(items => items.map(item => item.id === rule.id ? { ...item, weight: Number(event.target.value) } : item))} className="h-1.5 w-full cursor-pointer accent-teal-300" /></div>)}</div></div><ConditionFormulaPreview rules={rules} rootLogic={rootLogic} onRootLogicChange={logic => { setRootLogic(logic); setExpressionTree(tree => setGroupLogic(tree, "root-group", logic)); }} /><NestedExpressionEditor tree={expressionTree} rules={rules} onChange={tree => { setExpressionTree(tree); setRootLogic(tree.logic); }} />
        <ResearchExperimentSpecPanel presetId={selectedPresetId} presetName={persistedPresets.data?.find(item => item.id === selectedPresetId)?.name} />
        <PresetEvidencePanel presetId={selectedPresetId} presetName={persistedPresets.data?.find(item => item.id === selectedPresetId)?.name} />
        <div className="frosted-panel rounded-2xl p-5"><div className="flex items-center gap-3"><div className="rounded-xl bg-violet-400/10 p-2.5 text-violet-300"><Sparkles size={18} /></div><div><h2 className="font-bold text-white">프리셋 라이브러리</h2><p className="text-xs text-slate-500">전략을 저장하고 빠르게 전환합니다.</p></div></div><div className="mt-5 space-y-2">{persistedPresets.isLoading && <p className="py-2 text-xs text-slate-500">저장된 프리셋을 불러오는 중입니다.</p>}{persistedPresets.error && <div className="rounded-xl border border-rose-300/20 bg-rose-300/[0.06] p-3 text-xs text-rose-200"><p className="font-semibold">프리셋 목록을 불러오지 못했습니다.</p><p className="mt-1 opacity-75">{persistedPresets.error.message}</p><button onClick={() => persistedPresets.refetch()} className="mt-2 font-semibold underline underline-offset-2">다시 시도</button></div>}{persistedPresets.data?.map(item => <div key={item.id} className="flex items-center gap-2 rounded-xl border border-slate-800 bg-slate-900/35 p-1 transition-colors hover:border-slate-700"><button onClick={() => loadPreset(item)} className="min-w-0 flex-1 rounded-lg px-2.5 py-2.5 text-left"><span className="block truncate text-xs font-semibold text-slate-200">{item.name}</span><span className="mt-0.5 block text-[10px] text-slate-500">저장됨 · 조건 {Array.isArray(item.rulesJson) ? item.rulesJson.length : 0}개</span></button><button onClick={() => removePresetMutation.mutate({ id: item.id })} className="rounded-lg p-2 text-slate-500 hover:bg-rose-400/10 hover:text-rose-300" aria-label={`${item.name} 삭제`}><X size={14} /></button></div>)}{persistedPresets.data?.length === 0 && <p className="py-2 text-xs leading-relaxed text-slate-500">현재 저장된 프리셋이 없습니다. 위 조건 조합을 조정한 뒤 저장하세요.</p>}</div></div></section></div></div>;
}

export function ChartView() {
  const [symbol, setSymbol] = useState("005930");
  const validSymbol = /^\d{6}$/.test(symbol);
  const dailyBars = trpc.quant.dailyBars.useQuery({ symbol, maxPages: 3 }, { retry: false, enabled: validSymbol });
  const bars = dailyBars.data?.bars ?? [];
  const isLocalSnapshot = dailyBars.data?.source?.startsWith("ka10081_local_snapshot") ?? false;
  const provenance = isLocalSnapshot ? `로컬 ka10081 불변 스냅샷 · 데이터셋 #${dailyBars.data?.datasetId ?? "—"}` : dailyBars.data ? "키움 ka10081 읽기 전용 조회" : "실제 일봉 원본을 확인 중";
  const chart = useMemo(() => {
    if (bars.length < 2) return null;
    const low = Math.min(...bars.map(bar => bar.low)); const high = Math.max(...bars.map(bar => bar.high)); const range = Math.max(high - low, 1);
    const points = bars.map((bar, index) => `${(index / (bars.length - 1)) * 100},${88 - ((bar.close - low) / range) * 76}`).join(" ");
    return { points, low, high };
  }, [bars]);
  return <div className="enter-soft">
    <PageHeader eyebrow="TECHNICAL ANALYSIS" title="실데이터 종목 분석">
      <div className="relative"><Search className="absolute left-3 top-3 text-slate-500" size={15} /><Input value={symbol} onChange={event => setSymbol(event.target.value.replace(/\D/g, "").slice(0, 6))} className="h-10 w-[155px] border-slate-700 bg-slate-900 pl-9 font-mono text-xs text-slate-100" /></div>
      <Tabs defaultValue="1d"><TabsList className="bg-slate-900"><TabsTrigger value="1d">일</TabsTrigger><TabsTrigger value="1w" disabled>주</TabsTrigger><TabsTrigger value="1m" disabled>월</TabsTrigger></TabsList></Tabs>
    </PageHeader>
    <section className="frosted-panel rounded-2xl p-5">
      {dailyBars.isLoading ? <div className="flex min-h-[430px] flex-col items-center justify-center text-center"><Loader2 className="mb-4 animate-spin text-teal-300" size={28} /><p className="text-sm font-semibold text-slate-300">{symbol} 실제 일봉을 수집하는 중입니다.</p></div> : chart ? <>
        <div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><h2 className="font-bold text-white">{symbol} 일봉 종가 추이</h2><p className="mt-1 text-xs text-slate-500">키움 ka10081 · 수정주가 적용 · {bars.length}개 봉</p><p className={`mt-1 font-mono text-[10px] ${isLocalSnapshot ? "text-teal-200" : "text-slate-500"}`}>{provenance}{isLocalSnapshot && dailyBars.data?.datasetVersionKey ? ` · ${dailyBars.data.datasetVersionKey}` : ""}</p></div><div className="text-right"><p className="font-mono text-lg text-teal-200">{bars.at(-1)?.close.toLocaleString()}원</p><p className="text-[10px] text-slate-500">최근 종가</p></div></div>
        <div className="rounded-xl border border-slate-800 bg-slate-950/35 p-3"><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-64 w-full" role="img" aria-label={`${symbol} 실제 일봉 종가 차트`}><line x1="0" y1="12" x2="100" y2="12" stroke="currentColor" className="text-slate-800" strokeWidth="0.3"/><line x1="0" y1="88" x2="100" y2="88" stroke="currentColor" className="text-slate-800" strokeWidth="0.3"/><polyline points={chart.points} fill="none" stroke="#5eead4" strokeWidth="1.3" vectorEffect="non-scaling-stroke"/></svg><div className="mt-2 flex justify-between font-mono text-[10px] text-slate-500"><span>저가 {chart.low.toLocaleString()}</span><span>고가 {chart.high.toLocaleString()}</span></div></div>
        <div className="mt-5 grid gap-3 sm:grid-cols-3"><div className="rounded-xl border border-slate-800 bg-slate-950/25 p-3"><p className="text-[10px] text-slate-500">최근 거래량</p><p className="mt-1 font-mono text-sm text-slate-200">{bars.at(-1)?.volume.toLocaleString()}주</p></div><div className="rounded-xl border border-slate-800 bg-slate-950/25 p-3"><p className="text-[10px] text-slate-500">최근 거래대금</p><p className="mt-1 font-mono text-sm text-slate-200">{bars.at(-1)?.turnover.toLocaleString()}원</p></div><div className="rounded-xl border border-slate-800 bg-slate-950/25 p-3"><p className="text-[10px] text-slate-500">기준일</p><p className="mt-1 font-mono text-sm text-slate-200">{bars.at(-1)?.date}</p></div></div>
      </> : <div className="flex min-h-[430px] flex-col items-center justify-center px-6 text-center"><CandlestickChart className="mb-4 text-slate-600" size={30} /><h2 className="text-base font-bold text-slate-200">{symbol} 실제 일봉을 표시할 수 없습니다.</h2><p className="mt-3 max-w-md text-xs leading-relaxed text-slate-500">키움 접근 인증과 OAuth가 확인되면 ka10081에서 수집한 실제 일봉·거래량·거래대금만 차트에 표시됩니다. 예시 캔들·가격·지표를 제공하지 않습니다.</p>{dailyBars.error && <p className="mt-4 max-w-md rounded-lg border border-amber-300/15 bg-amber-300/[0.05] px-3 py-2 text-xs text-amber-200">{dailyBars.error.message}</p>}</div>}
    </section>
  </div>;
}

export function ResearchProtocolPanel() {
  return <><section className="mb-5 rounded-2xl border border-violet-300/15 bg-violet-300/[0.035] p-4"><div className="flex items-start gap-3"><div className="rounded-xl bg-violet-300/10 p-2 text-violet-200"><ShieldCheck size={17}/></div><div><h2 className="text-sm font-bold text-violet-100">재현 가능한 리서치 프로토콜</h2><p className="mt-1 text-xs leading-relaxed text-slate-400">조건식 버전, 실제 일봉 데이터셋, 기간, 정보 절단, 체결·비용 가정을 함께 기록해야 비교와 재실행이 가능합니다.</p></div></div><div className="mt-3 grid gap-2 text-[11px] text-slate-400 sm:grid-cols-3"><div className="rounded-lg border border-slate-800 bg-slate-950/35 p-2.5"><p className="font-semibold text-slate-200">1. 데이터셋 고정</p><p className="mt-1">유니버스·기간·수집 상태가 준비된 실제 일봉만 사용</p></div><div className="rounded-lg border border-slate-800 bg-slate-950/35 p-2.5"><p className="font-semibold text-slate-200">2. 미래정보 차단</p><p className="mt-1">신호 뒤 최소 1거래일을 분리하고 체결 시점을 명시</p></div><div className="rounded-lg border border-slate-800 bg-slate-950/35 p-2.5"><p className="font-semibold text-slate-200">3. 가정 잠금</p><p className="mt-1">수수료·슬리피지·보유 기간을 실험별로 함께 저장</p></div></div><p className="mt-3 text-[10px] leading-relaxed text-amber-200">HTS 조건식의 현재 후보는 워크포워드 관찰용입니다. 과거 백테스트에는 이 화면의 앱 조건식과 실제 일봉 데이터만 사용합니다.</p></section><ResearchExecutionPanel /><WalkForwardPanel /><EvolutionSearchPanel /><EvolutionCandidateDetailPanel /><EvolutionExpansionPanel /><ResearchComparisonPanel /></>;
}

export function EvolutionSearchPanel() {
  const datasets = trpc.research.listDatasets.useQuery(undefined, { retry: false }); const searches = trpc.research.listEvolutionSearches.useQuery(undefined, { retry: false });
  const [datasetId, setDatasetId] = useState<number | null>(null); const [searchId, setSearchId] = useState<number | null>(null); const [generationId, setGenerationId] = useState<number | null>(null); const [name, setName] = useState("고차원 조건식 세대 탐색"); const [populationSize, setPopulationSize] = useState("50"); const [symbol, setSymbol] = useState("005930");
  const generations = trpc.research.listEvolutionGenerations.useQuery({ searchId: searchId ?? 0 }, { enabled: Boolean(searchId), retry: false }); const generationSummaries = trpc.research.listEvolutionGenerationSummaries.useQuery({ searchId: searchId ?? 0 }, { enabled: Boolean(searchId), retry: false });
  const candidates = trpc.research.listEvolutionCandidates.useQuery({ searchId: searchId ?? 0, generationId: generationId ?? undefined }, { enabled: Boolean(searchId), retry: false });
  const create = trpc.research.createEvolutionSearch.useMutation({ onSuccess: async result => { setSearchId(result.searchId); setGenerationId(result.generationId); await searches.refetch(); toast.success(`${result.uniqueCandidateCount}개의 고유 유전자를 생성했습니다.`); }, onError: error => toast.error(error.message) });
  const evaluate = trpc.research.evaluateEvolutionCandidate.useMutation({ onSuccess: async () => { await candidates.refetch(); toast.success("고정 일봉으로 유전자 적합도를 기록했습니다."); }, onError: error => toast.error(error.message) });
  const advance = trpc.research.advanceEvolutionGeneration.useMutation({ onSuccess: async result => { setGenerationId(result.generationId); await generations.refetch(); await candidates.refetch(); toast.success(`세대 ${result.generationNumber}의 고유 파생 유전자를 생성했습니다.`); }, onError: error => toast.error(error.message) });
  const dataset = datasets.data?.find(item => item.id === datasetId); const search = searches.data?.find(item => item.id === searchId); const ready = dataset?.qualityStatus === "ready";
  const createSearch = () => { const population = Number(populationSize); if (!datasetId) { toast.error("ready 상태의 실제 데이터셋을 선택하세요."); return; } if (!Number.isInteger(population) || population < 10 || population > 100) { toast.error("웹 연구 배치는 10~100개 후보만 허용합니다."); return; } create.mutate({ datasetId, name, randomSeed: Math.floor(Date.now() % 2_000_000_000) + 1, configuration: { populationSize: population, minRules: 10, maxRules: 16, maxDepth: 3, allowedRuleTypes: ["macd_rising", "ma_position", "high_return", "turnover", "rsi", "bollinger", "stochastic", "atr_percent", "volume_ratio"], eliteCount: Math.min(10, Math.max(2, Math.floor(population * 0.15))), crossoverRate: 0.7, mutationRate: 0.25, minimumTrades: 5, maxDrawdownLimit: -25, holdingDays: 5, feeRate: 0.00015, slippageBps: 10, informationCutoffTradingDays: 1, entryTiming: "next_open" } }); };
  const countRules = (node: unknown): number => { if (!node || typeof node !== "object") return 0; const children = (node as { children?: unknown[] }).children; return children ? children.reduce<number>((total, child) => total + (typeof child === "object" && child !== null && "children" in child ? countRules(child) : 1), 0) : 1; };
  return <section className="mb-5 frosted-panel rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold text-white">진화형 조건식 탐색</h2><p className="mt-1 max-w-3xl text-xs leading-relaxed text-slate-500">10~16개 규칙과 중첩 논리 그룹을 유전자로 만들고, 지문이 중복되지 않는 후보만 기록합니다. 수익률 하나가 아니라 거래 수·낙폭을 포함한 적합도로 생존자를 고릅니다.</p></div><Badge className="border-fuchsia-300/20 bg-fuchsia-300/10 text-fuchsia-100">GENETIC RESEARCH</Badge></div><div className="mt-4 grid gap-3 lg:grid-cols-[1.5fr_1fr_0.6fr]"><label className="text-[11px] text-slate-400">고정 실제 데이터셋<Select value={String(datasetId ?? "none")} onValueChange={value => setDatasetId(value === "none" ? null : Number(value))}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue placeholder="ready 데이터셋 선택"/></SelectTrigger><SelectContent><SelectItem value="none">데이터셋 선택</SelectItem>{datasets.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.name} · {item.versionKey} · {item.qualityStatus}</SelectItem>)}</SelectContent></Select></label><label className="text-[11px] text-slate-400">탐색 이름<Input value={name} onChange={event => setName(event.target.value)} className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"/></label><label className="text-[11px] text-slate-400">후보 수<Input value={populationSize} onChange={event => setPopulationSize(event.target.value.replace(/\D/g, ""))} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label></div><div className="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-800 bg-slate-950/35 p-3"><p className="text-[11px] text-slate-500">{dataset ? `${dataset.versionKey} · ${dataset.barCount.toLocaleString()} bars · ${dataset.qualityStatus}` : "실제 원본이 고정된 ready 데이터셋만 세대 탐색을 시작할 수 있습니다."} <span className="text-fuchsia-200">웹 배치는 최대 100개이며, 수천 개 탐색은 별도 실행 경계에서 처리합니다.</span></p><Button onClick={createSearch} disabled={!ready || create.isPending} className="bg-fuchsia-300 text-slate-950 hover:bg-fuchsia-200"><Sparkles className="mr-2" size={15}/>{create.isPending ? "유전자 생성 중" : "첫 세대 생성"}</Button></div><div className="mt-5 grid gap-3 lg:grid-cols-[1fr_1.4fr]"><div className="rounded-xl border border-slate-800 bg-slate-950/25 p-3"><p className="text-xs font-semibold text-slate-200">탐색 · 세대 선택</p><label className="mt-3 block text-[11px] text-slate-400">탐색<Select value={String(searchId ?? "none")} onValueChange={value => { setSearchId(value === "none" ? null : Number(value)); setGenerationId(null); }}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue placeholder="탐색 선택"/></SelectTrigger><SelectContent><SelectItem value="none">생성된 탐색 선택</SelectItem>{searches.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.name} · seed {item.randomSeed} · {item.status}</SelectItem>)}</SelectContent></Select></label><label className="mt-3 block text-[11px] text-slate-400">세대<Select value={String(generationId ?? "none")} onValueChange={value => setGenerationId(value === "none" ? null : Number(value))}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue placeholder="세대 선택"/></SelectTrigger><SelectContent><SelectItem value="none">최신/전체 후보</SelectItem>{generations.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>세대 {item.generationNumber} · {item.uniqueCandidateCount} unique · {item.status}</SelectItem>)}</SelectContent></Select></label><label className="mt-3 block text-[11px] text-slate-400">평가 종목 코드<Input value={symbol} onChange={event => setSymbol(event.target.value.replace(/\D/g, "").slice(0, 6))} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label><Button onClick={() => searchId && advance.mutate({ searchId })} disabled={!searchId || advance.isPending} variant="outline" className="mt-3 w-full border-fuchsia-300/20 bg-fuchsia-300/[0.04] text-fuchsia-100 hover:bg-fuchsia-300/10 hover:text-white"><RefreshCw className="mr-2" size={15}/>{advance.isPending ? "다음 세대 생성 중" : "평가 생존자 → 다음 세대"}</Button>{generationSummaries.data?.length ? <div className="mt-4 space-y-2"><p className="text-[10px] font-semibold tracking-[0.14em] text-slate-500">GENERATION SCORECARD</p>{generationSummaries.data.map(summary => <div key={summary.generationId} className="rounded-lg border border-slate-800 bg-slate-950/45 p-2 text-[10px] text-slate-500"><div className="flex items-center justify-between"><b className="text-slate-200">세대 {summary.generationNumber}</b><span>{summary.evaluatedCandidateCount}/{summary.uniqueCandidateCount} 평가</span></div><div className="mt-1 grid grid-cols-4 gap-1"><span>생존 <b className="text-fuchsia-200">{summary.survivalRate === null ? "—" : `${(summary.survivalRate * 100).toFixed(0)}%`}</b></span><span>IN <b className="text-teal-200">{summary.averageInSampleReturn === null ? "—" : `${summary.averageInSampleReturn.toFixed(2)}%`}</b></span><span>OOS <b className="text-sky-200">{summary.averageOutOfSampleReturn === null ? "—" : `${summary.averageOutOfSampleReturn.toFixed(2)}%`}</b></span><span>WF <b className="text-violet-200">{summary.averageWalkForwardReturn === null ? "—" : `${summary.averageWalkForwardReturn.toFixed(2)}%`}</b></span></div>{summary.bestCandidate ? <Button onClick={() => { const bestCandidate = summary.bestCandidate; if (!bestCandidate) return; window.dispatchEvent(new CustomEvent("open-evolution-candidate-detail", { detail: { searchId, candidateId: bestCandidate.id } })); }} variant="ghost" className="mt-1 h-6 w-full justify-start px-0 text-[10px] text-fuchsia-200 hover:bg-transparent hover:text-fuchsia-100">상위 후보 상세 검토 <ChevronRight size={12}/></Button> : null}</div>)}</div> : null}</div><div className="rounded-xl border border-slate-800 bg-slate-950/25 p-3"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-slate-200">후보 유전자 상세</p><p className="font-mono text-[10px] text-slate-500">{candidates.data?.length ?? 0} CANDIDATES</p></div>{candidates.data?.length ? <div className="mt-3 max-h-80 space-y-2 overflow-y-auto pr-1">{candidates.data.slice(0, 30).map(candidate => { const metrics = candidate.inSampleMetricsJson as { metrics?: { totalReturn?: number; tradeCount?: number; maxDrawdown?: number }; symbol?: string } | null; return <div key={candidate.id} className="rounded-lg border border-slate-800 bg-slate-950/45 p-2.5"><div className="flex items-center justify-between gap-2"><span className="font-mono text-[10px] text-fuchsia-200">{candidate.fingerprint.slice(0, 12)}</span><Badge className="border-slate-700 bg-slate-800 text-[9px] text-slate-300">{candidate.origin} · {candidate.status}</Badge></div><div className="mt-2 grid grid-cols-4 gap-2 text-[10px] text-slate-500"><span>규칙 <b className="font-mono text-slate-200">{countRules(candidate.rootGenomeJson)}</b></span><span>최소점수 <b className="font-mono text-slate-200">{candidate.minimumScore}</b></span><span>적합도 <b className="font-mono text-teal-200">{candidate.fitnessScore ?? "—"}</b></span><span>부모 <b className="font-mono text-slate-200">{Array.isArray(candidate.parentCandidateIdsJson) ? candidate.parentCandidateIdsJson.join(",") : "seed"}</b></span></div>{metrics?.metrics ? <p className="mt-2 text-[10px] text-slate-500">{metrics.symbol} · 수익 {Number(metrics.metrics.totalReturn ?? 0).toFixed(2)}% · 거래 {metrics.metrics.tradeCount ?? 0} · MDD {Number(metrics.metrics.maxDrawdown ?? 0).toFixed(2)}%</p> : <Button onClick={() => evaluate.mutate({ candidateId: candidate.id, symbol })} disabled={evaluate.isPending || !/^\d{6}$/.test(symbol)} size="sm" variant="outline" className="mt-2 h-7 border-teal-300/20 bg-teal-300/[0.04] px-2 text-[10px] text-teal-100 hover:bg-teal-300/10 hover:text-white"><Play className="mr-1" size={12}/>고정 일봉 평가</Button>}</div>; })}</div> : <p className="py-10 text-center text-xs text-slate-500">탐색과 세대를 선택하면 고유 유전자·계보·적합도를 표시합니다.</p>}</div></div></section>;
}

export function EvolutionCandidateDetailPanel() {
  const searches = trpc.research.listEvolutionSearches.useQuery(undefined, { retry: false }); const [searchId, setSearchId] = useState<number | null>(null); const [candidateId, setCandidateId] = useState<number | null>(null); const [validationStartDate, setValidationStartDate] = useState(""); const [trainingDays, setTrainingDays] = useState("120"); const [validationDays, setValidationDays] = useState("40"); const [stepDays, setStepDays] = useState("20");
  const candidates = trpc.research.listEvolutionCandidates.useQuery({ searchId: searchId ?? 0 }, { enabled: Boolean(searchId), retry: false }); const selected = candidates.data?.find(item => item.id === candidateId);
  const names: Record<string, string> = { macd_rising: "MACD 방향", ma_position: "이동평균 위치", high_return: "N일 고가 등락", turnover: "거래대금", rsi: "RSI", bollinger: "볼린저 밴드", stochastic: "스토캐스틱", atr_percent: "ATR 비율", volume_ratio: "거래량 비율" };
  const describe = (node: unknown): React.ReactNode => { if (!node || typeof node !== "object") return null; const item = node as { logic?: string; type?: string; config?: Record<string, unknown>; children?: unknown[] }; if (item.children) return <li><b className="text-fuchsia-200">{item.logic}</b><ul className="ml-4 mt-1 space-y-1 border-l border-slate-800 pl-3">{item.children.map((child, index) => <React.Fragment key={index}>{describe(child)}</React.Fragment>)}</ul></li>; return <li><b className="text-slate-200">{names[item.type ?? ""] ?? item.type}</b><span className="ml-2 font-mono text-slate-500">{Object.entries(item.config ?? {}).map(([key, value]) => `${key}=${value}`).join(" · ")}</span></li>; };
  const metrics = selected?.inSampleMetricsJson as { metrics?: { totalReturn?: number; maxDrawdown?: number; tradeCount?: number; winRate?: number }; result?: { trades?: Array<unknown> }; datasetVersionKey?: string; symbol?: string } | null;
  const outOfSample = selected?.outOfSampleMetricsJson as { metrics?: { totalReturn?: number; maxDrawdown?: number; tradeCount?: number; winRate?: number }; datasetVersionKey?: string; symbol?: string; validationStartDate?: string } | null;
  const walkForward = selected?.walkForwardMetricsJson as { datasetVersionKey?: string; symbol?: string; configuration?: { trainingDays?: number; validationDays?: number; stepDays?: number }; result?: { foldCount?: number; totalReturn?: number; winRate?: number; tradeCount?: number; worstFoldDrawdown?: number } } | null;
  const validate = trpc.research.validateEvolutionCandidate.useMutation({ onSuccess: async () => { await candidates.refetch(); toast.success("독립 아웃오브샘플 성과를 기록했습니다."); }, onError: error => toast.error(error.message) });
  const runWalkForward = trpc.research.runEvolutionCandidateWalkForward.useMutation({ onSuccess: async () => { await candidates.refetch(); toast.success("생존 유전자의 워크포워드 성과를 기록했습니다."); }, onError: error => toast.error(error.message) });
  useEffect(() => { const open = (event: Event) => { const detail = (event as CustomEvent<{ searchId?: number; candidateId?: number }>).detail; if (!detail?.searchId || !detail.candidateId) return; setSearchId(detail.searchId); setCandidateId(detail.candidateId); document.getElementById("evolution-candidate-detail")?.scrollIntoView({ behavior: "smooth", block: "start" }); }; window.addEventListener("open-evolution-candidate-detail", open); return () => window.removeEventListener("open-evolution-candidate-detail", open); }, []);
  return <section id="evolution-candidate-detail" className="mb-5 frosted-panel rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold text-white">유전자 상세 검토 · 계보</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">생존 또는 파생 조건식의 전체 논리 트리·파라미터·부모·변이·적합도와 고정 실제 일봉 성과를 검토합니다.</p></div><Badge className="border-fuchsia-300/20 bg-fuchsia-300/10 text-fuchsia-100">GENOME LEDGER</Badge></div><div className="mt-4 grid gap-3 md:grid-cols-2"><label className="text-[11px] text-slate-400">탐색<Select value={String(searchId ?? "none")} onValueChange={value => { setSearchId(value === "none" ? null : Number(value)); setCandidateId(null); }}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue placeholder="탐색 선택"/></SelectTrigger><SelectContent><SelectItem value="none">탐색 선택</SelectItem>{searches.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.name} · seed {item.randomSeed}</SelectItem>)}</SelectContent></Select></label><label className="text-[11px] text-slate-400">후보 유전자<Select value={String(candidateId ?? "none")} onValueChange={value => setCandidateId(value === "none" ? null : Number(value))}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue placeholder="후보 선택"/></SelectTrigger><SelectContent><SelectItem value="none">후보 선택</SelectItem>{candidates.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.fingerprint.slice(0, 12)} · {item.origin} · {item.status}</SelectItem>)}</SelectContent></Select></label></div>{selected ? <div className="mt-4 grid gap-4 xl:grid-cols-[1.35fr_0.65fr]"><div className="rounded-xl border border-slate-800 bg-slate-950/35 p-4"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-mono text-xs text-fuchsia-200">{selected.fingerprint}</p><Badge className="border-slate-700 bg-slate-800 text-slate-300">{selected.origin} · {selected.status}</Badge></div><ul className="mt-4 space-y-1 text-[11px] leading-relaxed text-slate-400">{describe(selected.rootGenomeJson)}</ul></div><div className="space-y-3"><div className="rounded-xl border border-slate-800 bg-slate-950/35 p-3 text-[11px] text-slate-500"><p>최소 점수 <b className="ml-1 font-mono text-slate-200">{selected.minimumScore}</b></p><p className="mt-1">적합도 <b className="ml-1 font-mono text-teal-200">{selected.fitnessScore ?? "미평가"}</b></p><p className="mt-1">부모 <b className="ml-1 font-mono text-slate-200">{Array.isArray(selected.parentCandidateIdsJson) && selected.parentCandidateIdsJson.length ? selected.parentCandidateIdsJson.join(", ") : "초기 시드"}</b></p><p className="mt-1">변이 <b className="ml-1 font-mono text-slate-200">{selected.mutationJson ? JSON.stringify(selected.mutationJson) : "없음"}</b></p></div>{metrics?.metrics ? <div className="rounded-xl border border-teal-300/15 bg-teal-300/[0.04] p-3 text-[11px] text-slate-400"><p className="font-semibold text-teal-100">인샘플 성과</p><p className="mt-2">{metrics.datasetVersionKey} · {metrics.symbol}</p><p className="mt-1">수익 <b className="font-mono text-teal-200">{Number(metrics.metrics.totalReturn ?? 0).toFixed(2)}%</b> · 승률 <b className="font-mono text-slate-200">{Number(metrics.metrics.winRate ?? 0).toFixed(2)}%</b></p><p className="mt-1">거래 <b className="font-mono text-slate-200">{metrics.metrics.tradeCount ?? 0}</b> · MDD <b className="font-mono text-rose-200">{Number(metrics.metrics.maxDrawdown ?? 0).toFixed(2)}%</b></p></div> : <p className="rounded-xl border border-amber-300/15 bg-amber-300/[0.04] p-3 text-[11px] text-amber-100">아직 고정 실제 일봉 평가가 없습니다.</p>}{outOfSample?.metrics ? <div className="rounded-xl border border-sky-300/15 bg-sky-300/[0.04] p-3 text-[11px] text-slate-400"><p className="font-semibold text-sky-100">독립 아웃오브샘플 성과</p><p className="mt-2">{outOfSample.datasetVersionKey} · {outOfSample.symbol} · {outOfSample.validationStartDate} 이후</p><p className="mt-1">수익 <b className="font-mono text-sky-200">{Number(outOfSample.metrics.totalReturn ?? 0).toFixed(2)}%</b> · 승률 <b className="font-mono text-slate-200">{Number(outOfSample.metrics.winRate ?? 0).toFixed(2)}%</b></p><p className="mt-1">거래 <b className="font-mono text-slate-200">{outOfSample.metrics.tradeCount ?? 0}</b> · MDD <b className="font-mono text-rose-200">{Number(outOfSample.metrics.maxDrawdown ?? 0).toFixed(2)}%</b></p></div> : <div className="rounded-xl border border-sky-300/15 bg-sky-300/[0.03] p-3"><p className="text-[11px] font-semibold text-sky-100">독립 아웃오브샘플 검증</p><div className="mt-2 flex gap-2"><Input aria-label="독립 검증 시작일" value={validationStartDate} onChange={event => setValidationStartDate(event.target.value)} placeholder="YYYY-MM-DD" className="h-8 border-slate-700 bg-slate-950 font-mono text-[11px] text-slate-100"/><Button onClick={() => selected && metrics?.symbol && validate.mutate({ candidateId: selected.id, symbol: metrics.symbol, validationStartDate })} disabled={validate.isPending || !/^\d{4}-\d{2}-\d{2}$/.test(validationStartDate) || !metrics?.symbol} size="sm" variant="outline" className="h-8 shrink-0 border-sky-300/20 bg-sky-300/[0.04] px-2 text-[10px] text-sky-100 hover:bg-sky-300/10 hover:text-white">{validate.isPending ? "검증 중" : "독립 검증"}</Button></div></div>}{walkForward?.result ? <div className="rounded-xl border border-violet-300/15 bg-violet-300/[0.04] p-3 text-[11px] text-slate-400"><p className="font-semibold text-violet-100">반복 워크포워드 성과</p><p className="mt-2">{walkForward.datasetVersionKey} · {walkForward.symbol} · {walkForward.result.foldCount ?? 0} folds</p><p className="mt-1">수익 <b className="font-mono text-violet-200">{Number(walkForward.result.totalReturn ?? 0).toFixed(2)}%</b> · 승률 <b className="font-mono text-slate-200">{Number(walkForward.result.winRate ?? 0).toFixed(2)}%</b></p><p className="mt-1">거래 <b className="font-mono text-slate-200">{walkForward.result.tradeCount ?? 0}</b> · 최악 폴드 MDD <b className="font-mono text-rose-200">{Number(walkForward.result.worstFoldDrawdown ?? 0).toFixed(2)}%</b></p></div> : <div className="rounded-xl border border-violet-300/15 bg-violet-300/[0.03] p-3"><p className="text-[11px] font-semibold text-violet-100">반복 워크포워드 검증</p><div className="mt-2 grid grid-cols-3 gap-2"><Input aria-label="워크포워드 학습일" value={trainingDays} onChange={event => setTrainingDays(event.target.value.replace(/\D/g, ""))} placeholder="학습일" className="h-8 border-slate-700 bg-slate-950 font-mono text-[11px] text-slate-100"/><Input aria-label="워크포워드 검증일" value={validationDays} onChange={event => setValidationDays(event.target.value.replace(/\D/g, ""))} placeholder="검증일" className="h-8 border-slate-700 bg-slate-950 font-mono text-[11px] text-slate-100"/><Input aria-label="워크포워드 이동일" value={stepDays} onChange={event => setStepDays(event.target.value.replace(/\D/g, ""))} placeholder="이동일" className="h-8 border-slate-700 bg-slate-950 font-mono text-[11px] text-slate-100"/></div><Button onClick={() => selected && metrics?.symbol && runWalkForward.mutate({ candidateId: selected.id, symbol: metrics.symbol, trainingDays: Number(trainingDays), validationDays: Number(validationDays), stepDays: Number(stepDays) })} disabled={selected.status !== "survived" || runWalkForward.isPending || !metrics?.symbol || Number(trainingDays) < 60 || Number(validationDays) < 5 || Number(stepDays) < 1} size="sm" variant="outline" className="mt-2 h-8 border-violet-300/20 bg-violet-300/[0.04] px-2 text-[10px] text-violet-100 hover:bg-violet-300/10 hover:text-white">{runWalkForward.isPending ? "분석 중" : "워크포워드 실행"}</Button>{selected.status !== "survived" ? <p className="mt-2 text-[10px] text-amber-100">워크포워드는 선발된 survived 유전자에서만 실행할 수 있습니다.</p> : null}</div>}</div></div> : <p className="mt-5 py-8 text-center text-xs text-slate-500">탐색과 후보를 선택하면 전체 조건식 트리와 계보·성과를 표시합니다.</p>}</section>;
}

export function EvolutionExpansionPanel() {
  const searches = trpc.research.listEvolutionSearches.useQuery(undefined, { retry: false }); const [searchId, setSearchId] = useState<number | null>(null); const [candidateId, setCandidateId] = useState<number | null>(null); const [targetId, setTargetId] = useState(""); const [nextValue, setNextValue] = useState(""); const [nextLogic, setNextLogic] = useState<"AND" | "OR" | "NOT">("AND"); const [derived, setDerived] = useState<{ candidateId: number; fingerprint: string; mutation: { key?: string; previous?: unknown; next?: unknown } | null } | null>(null);
  const candidates = trpc.research.listEvolutionCandidates.useQuery({ searchId: searchId ?? 0 }, { enabled: Boolean(searchId), retry: false }); const selected = candidates.data?.find(item => item.id === candidateId && item.status === "survived");
  const nodes = useMemo(() => { const output: Array<{ id: string; label: string; kind: "rule" | "group"; key?: string; previous?: number }> = []; const visit = (node: unknown) => { if (!node || typeof node !== "object") return; const item = node as { id?: string; logic?: string; type?: string; weight?: number; config?: Record<string, unknown>; children?: unknown[] }; if (!item.id) return; if (item.children) { output.push({ id: item.id, label: `논리 그룹 · ${item.logic}`, kind: "group" }); item.children.forEach(visit); return; } output.push({ id: `${item.id}:weight`, label: `${item.type} · weight (${item.weight})`, kind: "rule", key: "weight", previous: item.weight }); Object.entries(item.config ?? {}).forEach(([key, value]) => { if (typeof value === "number") output.push({ id: `${item.id}:${key}`, label: `${item.type} · ${key} (${value})`, kind: "rule", key, previous: value }); }); }; visit(selected?.rootGenomeJson); return output; }, [selected]);
  const target = nodes.find(item => item.id === targetId); const expand = trpc.research.manuallyExpandEvolutionCandidate.useMutation({ onSuccess: async result => { setDerived({ candidateId: result.candidateId, fingerprint: result.fingerprint, mutation: result.mutation as { key?: string; previous?: unknown; next?: unknown } | null }); await candidates.refetch(); toast.success("원본 유전자를 보존한 확장 실험 분기를 생성했습니다."); }, onError: error => toast.error(error.message) });
  const selectTarget = (value: string) => { setTargetId(value); const choice = nodes.find(item => item.id === value); if (choice?.kind === "rule") setNextValue(String(choice.previous ?? "")); };
  return <section className="mb-5 frosted-panel rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold text-white">생존 유전자 확장 실험</h2><p className="mt-1 max-w-3xl text-xs leading-relaxed text-slate-500">선발된 생존 유전자에서 숫자형 규칙 파라미터 또는 논리 그룹만 선택해 변경합니다. 원본은 보존하고, 파생 후보는 별도 단일 세대로 기록되어 동일 연구 가정의 중복을 허용하지 않습니다.</p></div><Badge className="border-amber-300/20 bg-amber-300/10 text-amber-100">MANUAL BRANCH</Badge></div><div className="mt-4 grid gap-3 md:grid-cols-2"><label className="text-[11px] text-slate-400">부모 탐색<Select value={String(searchId ?? "none")} onValueChange={value => { setSearchId(value === "none" ? null : Number(value)); setCandidateId(null); setTargetId(""); setDerived(null); }}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue placeholder="탐색 선택"/></SelectTrigger><SelectContent><SelectItem value="none">탐색 선택</SelectItem>{searches.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.name} · seed {item.randomSeed}</SelectItem>)}</SelectContent></Select></label><label className="text-[11px] text-slate-400">생존 부모 유전자<Select value={String(candidateId ?? "none")} onValueChange={value => { setCandidateId(value === "none" ? null : Number(value)); setTargetId(""); setDerived(null); }}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue placeholder="survived 후보 선택"/></SelectTrigger><SelectContent><SelectItem value="none">생존 후보 선택</SelectItem>{candidates.data?.filter(item => item.status === "survived").map(item => <SelectItem key={item.id} value={String(item.id)}>{item.fingerprint.slice(0, 12)} · fitness {item.fitnessScore ?? "—"}</SelectItem>)}</SelectContent></Select></label></div>{selected ? <div className="mt-4 grid gap-3 lg:grid-cols-[1.15fr_0.85fr]"><div className="rounded-xl border border-slate-800 bg-slate-950/35 p-3"><p className="text-[11px] font-semibold text-slate-200">변경 대상</p><Select value={targetId || "none"} onValueChange={selectTarget}><SelectTrigger className="mt-2 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue placeholder="규칙 파라미터 또는 논리 그룹 선택"/></SelectTrigger><SelectContent><SelectItem value="none">변경 대상 선택</SelectItem>{nodes.map(item => <SelectItem key={item.id} value={item.id}>{item.label}</SelectItem>)}</SelectContent></Select>{target?.kind === "rule" ? <label className="mt-3 block text-[11px] text-slate-400">파생 값<Input aria-label="파생 값" value={nextValue} onChange={event => setNextValue(event.target.value)} inputMode="decimal" className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label> : target?.kind === "group" ? <label className="mt-3 block text-[11px] text-slate-400">파생 논리<Select value={nextLogic} onValueChange={value => setNextLogic(value as "AND" | "OR" | "NOT")}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="AND">AND</SelectItem><SelectItem value="OR">OR</SelectItem><SelectItem value="NOT">NOT</SelectItem></SelectContent></Select></label> : null}<Button onClick={() => { if (!selected || !target) return; const change = target.kind === "rule" ? { kind: "rule_numeric" as const, targetNodeId: target.id.split(":")[0]!, key: target.key!, next: Number(nextValue) } : { kind: "group_logic" as const, targetNodeId: target.id, next: nextLogic }; expand.mutate({ candidateId: selected.id, change }); }} disabled={!target || expand.isPending || (target.kind === "rule" && (!Number.isFinite(Number(nextValue)) || Number(nextValue) < 0))} variant="outline" className="mt-3 border-amber-300/20 bg-amber-300/[0.04] text-amber-100 hover:bg-amber-300/10 hover:text-white"><Sparkles className="mr-2" size={15}/>{expand.isPending ? "분기 생성 중" : "확장 유전자 생성"}</Button></div><div className="rounded-xl border border-amber-300/15 bg-amber-300/[0.035] p-3 text-[11px] text-slate-500"><p className="font-semibold text-amber-100">원본 · 파생 차이</p><p className="mt-2">원본 <b className="font-mono text-slate-200">{selected.fingerprint}</b></p>{derived ? <><p className="mt-2">파생 <b className="font-mono text-amber-100">{derived.fingerprint}</b></p><p className="mt-2">변경 <b className="font-mono text-slate-200">{derived.mutation?.key}: {String(derived.mutation?.previous)} → {String(derived.mutation?.next)}</b></p><p className="mt-1">새 후보 ID <b className="font-mono text-slate-200">{derived.candidateId}</b>는 평가 전 상태로 분리 저장되었습니다.</p></> : <p className="mt-2">변경 대상을 선택하면 원본과 다른 부분만 표시합니다. 생성된 후보는 고정 실제 일봉 평가를 거쳐 별도로 선발합니다.</p>}</div></div> : <p className="mt-5 rounded-xl border border-slate-800 bg-slate-950/30 p-4 text-center text-xs text-slate-500">확장할 탐색과 survived 상태의 부모 유전자를 선택하세요.</p>}</section>;
}

export function ResearchExecutionPanel() {
  const datasets = trpc.research.listDatasets.useQuery(undefined, { retry: false });
  const experiments = trpc.research.listExperiments.useQuery(undefined, { retry: false });
  const [experimentId, setExperimentId] = useState<number | null>(null); const [symbol, setSymbol] = useState("005930"); const [initialCapital, setInitialCapital] = useState("10000000");
  const collect = trpc.research.collectDataset.useMutation({ onSuccess: async () => { await datasets.refetch(); toast.success("실주가 원본을 버전 데이터셋으로 고정했습니다."); }, onError: error => toast.error(error.message) });
  const execute = trpc.research.runExperiment.useMutation({ onSuccess: async () => { await experiments.refetch(); toast.success("고정 데이터셋 실험을 완료했습니다."); }, onError: error => toast.error(error.message) });
  const experiment = experiments.data?.find(item => item.id === experimentId); const dataset = datasets.data?.find(item => item.id === experiment?.datasetId); const ready = dataset?.qualityStatus === "ready";
  const run = () => { if (!experiment) { toast.error("저장된 실험 명세를 선택하세요."); return; } if (!/^\d{6}$/.test(symbol)) { toast.error("6자리 종목 코드를 입력하세요."); return; } const capital = Number(initialCapital); if (!Number.isInteger(capital) || capital <= 0) { toast.error("초기 자본금을 확인하세요."); return; } execute.mutate({ experimentId: experiment.id, symbol, initialCapital: capital, minScore: 70 }); };
  return <section className="mb-5 frosted-panel rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold text-white">고정 데이터셋 실험 실행</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">실험 명세에 연결된 데이터셋만 수집·실행합니다. 수집 후 원본은 같은 버전에서 수정하지 않습니다.</p></div><Badge className="border-teal-300/20 bg-teal-300/10 text-teal-100">FROZEN DATA ONLY</Badge></div><div className="mt-4 grid gap-3 md:grid-cols-[1.4fr_0.7fr_0.7fr]"><label className="text-[11px] text-slate-400">저장 실험 명세<Select value={String(experimentId ?? "none")} onValueChange={value => setExperimentId(value === "none" ? null : Number(value))}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">실험 명세 선택</SelectItem>{experiments.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.name} · {item.status}</SelectItem>)}</SelectContent></Select></label><label className="text-[11px] text-slate-400">종목 코드<Input value={symbol} onChange={event => setSymbol(event.target.value.replace(/\D/g, "").slice(0, 6))} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label><label className="text-[11px] text-slate-400">초기 자본금<Input value={initialCapital} onChange={event => setInitialCapital(event.target.value.replace(/\D/g, ""))} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label></div><div className="mt-3 rounded-xl border border-slate-800 bg-slate-950/35 p-3"><p className="text-xs font-semibold text-slate-200">{dataset ? `${dataset.name} · ${dataset.versionKey}` : "연결 데이터셋 미선택"}</p><p className="mt-1 text-[11px] text-slate-500">{dataset ? `${dataset.startDate} ~ ${dataset.endDate} · ${dataset.barCount.toLocaleString()} bars · ${dataset.qualityStatus}` : "실험 명세를 선택하면 연결된 실주가 데이터셋이 표시됩니다."}</p></div><div className="mt-3 flex flex-wrap justify-end gap-2"><Button variant="outline" onClick={() => dataset && collect.mutate({ datasetId: dataset.id, maxPagesPerSymbol: 10 })} disabled={!dataset || dataset.qualityStatus !== "draft" || collect.isPending} className="border-violet-300/20 bg-violet-300/[0.05] text-violet-100 hover:bg-violet-300/10 hover:text-white"><Download className="mr-2" size={15}/>{collect.isPending ? "원본 수집 중" : "원본 일봉 고정 수집"}</Button><Button onClick={run} disabled={!experiment || !ready || execute.isPending} className="bg-teal-300 text-slate-950 hover:bg-teal-200"><Play className="mr-2" size={15}/>{execute.isPending ? "실험 실행 중" : "고정 데이터셋 실행"}</Button></div>{execute.data ? <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4"><p className="rounded-lg bg-slate-950/45 p-2 text-[10px] text-slate-400">수익률 <b className="ml-1 font-mono text-teal-200">{execute.data.result.totalReturn.toFixed(2)}%</b></p><p className="rounded-lg bg-slate-950/45 p-2 text-[10px] text-slate-400">승률 <b className="ml-1 font-mono text-slate-200">{execute.data.result.winRate.toFixed(2)}%</b></p><p className="rounded-lg bg-slate-950/45 p-2 text-[10px] text-slate-400">거래 <b className="ml-1 font-mono text-slate-200">{execute.data.result.tradeCount}</b></p><p className="rounded-lg bg-slate-950/45 p-2 text-[10px] text-slate-400">MDD <b className="ml-1 font-mono text-rose-200">{execute.data.result.maxDrawdown.toFixed(2)}%</b></p></div> : null}</section>;
}

export function WalkForwardPanel() {
  const experiments = trpc.research.listExperiments.useQuery(undefined, { retry: false }); const runs = trpc.research.listWalkForwardRuns.useQuery(undefined, { retry: false });
  const [experimentId, setExperimentId] = useState<number | null>(null); const [runId, setRunId] = useState<number | null>(null); const [symbol, setSymbol] = useState("005930"); const [trainingDays, setTrainingDays] = useState("252"); const [validationDays, setValidationDays] = useState("63"); const [stepDays, setStepDays] = useState("63");
  const create = trpc.research.createWalkForwardRun.useMutation({ onSuccess: async result => { setRunId(result.id); await runs.refetch(); toast.success("워크포워드 실행 계획을 저장했습니다."); }, onError: error => toast.error(error.message) });
  const execute = trpc.research.runWalkForward.useMutation({ onSuccess: async () => { await runs.refetch(); toast.success("워크포워드 분석을 완료했습니다."); }, onError: error => toast.error(error.message) });
  const savePlan = () => { if (!experimentId) { toast.error("워크포워드할 저장 실험을 선택하세요."); return; } const training = Number(trainingDays); const validation = Number(validationDays); const step = Number(stepDays); if (![training, validation, step].every(Number.isInteger) || training < 20 || validation < 5 || step < 1) { toast.error("학습·검증·이동 기간을 확인하세요."); return; } create.mutate({ experimentId, trainingDays: training, validationDays: validation, stepDays: step }); };
  const run = () => { if (!runId || !/^\d{6}$/.test(symbol)) { toast.error("실행 기록과 6자리 종목 코드를 확인하세요."); return; } execute.mutate({ walkForwardRunId: runId, symbol, minScore: 70 }); };
  return <section className="mb-5 frosted-panel rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold text-white">워크포워드 분석</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">각 폴드는 이전 학습 구간만 참조한 뒤, 이후 검증 구간에서만 거래를 평가합니다.</p></div><Badge className="border-amber-300/20 bg-amber-300/10 text-amber-100">OUT-OF-SAMPLE</Badge></div><div className="mt-4 grid gap-3 md:grid-cols-4"><label className="text-[11px] text-slate-400 md:col-span-2">저장 실험<Select value={String(experimentId ?? "none")} onValueChange={value => setExperimentId(value === "none" ? null : Number(value))}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">실험 명세 선택</SelectItem>{experiments.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.name}</SelectItem>)}</SelectContent></Select></label><label className="text-[11px] text-slate-400">학습일<Input value={trainingDays} onChange={event => setTrainingDays(event.target.value)} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label><label className="text-[11px] text-slate-400">검증일<Input value={validationDays} onChange={event => setValidationDays(event.target.value)} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label></div><div className="mt-3 grid gap-3 md:grid-cols-4"><label className="text-[11px] text-slate-400">이동일<Input value={stepDays} onChange={event => setStepDays(event.target.value)} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label><label className="text-[11px] text-slate-400">종목 코드<Input value={symbol} onChange={event => setSymbol(event.target.value.replace(/\D/g, "").slice(0, 6))} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label><label className="text-[11px] text-slate-400 md:col-span-2">실행 기록<Select value={String(runId ?? "none")} onValueChange={value => setRunId(value === "none" ? null : Number(value))}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">워크포워드 기록 선택</SelectItem>{runs.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>#{item.id} · {item.status}</SelectItem>)}</SelectContent></Select></label></div><div className="mt-4 flex flex-wrap justify-end gap-2"><Button variant="outline" onClick={savePlan} disabled={create.isPending} className="border-amber-300/20 bg-amber-300/[0.05] text-amber-100 hover:bg-amber-300/10 hover:text-white"><Save className="mr-2" size={15}/>{create.isPending ? "계획 저장 중" : "실행 계획 저장"}</Button><Button onClick={run} disabled={!runId || execute.isPending} className="bg-teal-300 text-slate-950 hover:bg-teal-200"><Play className="mr-2" size={15}/>{execute.isPending ? "분석 실행 중" : "워크포워드 실행"}</Button></div>{execute.data ? <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4"><p className="rounded-lg bg-slate-950/45 p-2 text-[10px] text-slate-400">폴드 <b className="ml-1 font-mono text-slate-200">{execute.data.result.foldCount}</b></p><p className="rounded-lg bg-slate-950/45 p-2 text-[10px] text-slate-400">수익률 <b className="ml-1 font-mono text-teal-200">{execute.data.result.totalReturn.toFixed(2)}%</b></p><p className="rounded-lg bg-slate-950/45 p-2 text-[10px] text-slate-400">승률 <b className="ml-1 font-mono text-slate-200">{execute.data.result.winRate.toFixed(2)}%</b></p><p className="rounded-lg bg-slate-950/45 p-2 text-[10px] text-slate-400">최악 폴드 MDD <b className="ml-1 font-mono text-rose-200">{execute.data.result.worstFoldDrawdown.toFixed(2)}%</b></p></div> : null}</section>;
}

export function ResearchComparisonPanel() {
  const experiments = trpc.research.listExperiments.useQuery(undefined, { retry: false }); const walkForward = trpc.research.listWalkForwardRuns.useQuery(undefined, { retry: false });
  const completedExperiments = (experiments.data ?? []).flatMap(item => { const payload = item.resultsJson as { result?: { totalReturn?: number; winRate?: number; tradeCount?: number; maxDrawdown?: number }; datasetVersionKey?: string; symbol?: string } | null; return payload?.result ? [{ id: item.id, name: item.name, status: item.status, datasetVersionKey: payload.datasetVersionKey ?? "—", symbol: payload.symbol ?? "—", result: payload.result }] : []; });
  const completedWalkForward = (walkForward.data ?? []).flatMap(item => { const payload = item.resultsJson as { result?: { foldCount?: number; totalReturn?: number; winRate?: number; tradeCount?: number; worstFoldDrawdown?: number }; datasetVersionKey?: string; symbol?: string } | null; return payload?.result ? [{ id: item.id, datasetVersionKey: payload.datasetVersionKey ?? "—", symbol: payload.symbol ?? "—", result: payload.result }] : []; });
  return <section className="mb-5 frosted-panel rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold text-white">성과 비교 · 드릴다운</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">완료된 고정 데이터셋 실행만 비교합니다. 데이터셋 버전·종목이 다른 결과는 직접적인 우열 판단 대신 별도 기록으로 봐야 합니다.</p></div><Badge className="border-sky-300/20 bg-sky-300/10 text-sky-100">RESULT LEDGER</Badge></div><div className="mt-4 grid gap-4 xl:grid-cols-2"><div className="rounded-xl border border-slate-800 bg-slate-950/25 p-3"><p className="text-xs font-semibold text-slate-200">단일 실험 결과</p>{completedExperiments.length ? <div className="mt-3 space-y-2">{completedExperiments.slice(0, 5).map(item => <div key={item.id} className="rounded-lg border border-slate-800 bg-slate-950/45 p-2.5"><div className="flex items-center justify-between gap-2"><p className="truncate text-xs font-semibold text-slate-200">{item.name}</p><span className="font-mono text-[10px] text-slate-500">{item.symbol} · {item.datasetVersionKey}</span></div><div className="mt-2 grid grid-cols-4 gap-2 text-[10px] text-slate-500"><span>수익 <b className="ml-1 font-mono text-teal-200">{Number(item.result.totalReturn ?? 0).toFixed(2)}%</b></span><span>승률 <b className="ml-1 font-mono text-slate-200">{Number(item.result.winRate ?? 0).toFixed(2)}%</b></span><span>거래 <b className="ml-1 font-mono text-slate-200">{item.result.tradeCount ?? 0}</b></span><span>MDD <b className="ml-1 font-mono text-rose-200">{Number(item.result.maxDrawdown ?? 0).toFixed(2)}%</b></span></div></div>)}</div> : <p className="py-6 text-center text-xs text-slate-500">완료된 고정 데이터셋 실험이 없습니다.</p>}</div><div className="rounded-xl border border-slate-800 bg-slate-950/25 p-3"><p className="text-xs font-semibold text-slate-200">워크포워드 결과</p>{completedWalkForward.length ? <div className="mt-3 space-y-2">{completedWalkForward.slice(0, 5).map(item => <div key={item.id} className="rounded-lg border border-slate-800 bg-slate-950/45 p-2.5"><div className="flex items-center justify-between gap-2"><p className="text-xs font-semibold text-slate-200">워크포워드 #{item.id}</p><span className="font-mono text-[10px] text-slate-500">{item.symbol} · {item.datasetVersionKey}</span></div><div className="mt-2 grid grid-cols-4 gap-2 text-[10px] text-slate-500"><span>폴드 <b className="ml-1 font-mono text-slate-200">{item.result.foldCount ?? 0}</b></span><span>수익 <b className="ml-1 font-mono text-teal-200">{Number(item.result.totalReturn ?? 0).toFixed(2)}%</b></span><span>승률 <b className="ml-1 font-mono text-slate-200">{Number(item.result.winRate ?? 0).toFixed(2)}%</b></span><span>최악MDD <b className="ml-1 font-mono text-rose-200">{Number(item.result.worstFoldDrawdown ?? 0).toFixed(2)}%</b></span></div></div>)}</div> : <p className="py-6 text-center text-xs text-slate-500">완료된 워크포워드 분석이 없습니다.</p>}</div></div></section>;
}

export function ResearchDatasetPanel() {
  const datasets = trpc.research.listDatasets.useQuery(undefined, { retry: false });
  const [name, setName] = useState("");
  const [versionKey, setVersionKey] = useState("");
  const [universeText, setUniverseText] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const create = trpc.research.createDataset.useMutation({
    onSuccess: async () => { await datasets.refetch(); toast.success("리서치 데이터셋 초안을 저장했습니다."); },
    onError: error => toast.error(error.message),
  });
  const symbols = Array.from(new Set(universeText.split(/[\s,]+/).map(value => value.trim()).filter(value => /^\d{6}$/.test(value))));
  const save = () => {
    if (name.trim().length < 2) { toast.error("데이터셋 이름을 2자 이상 입력하세요."); return; }
    if (versionKey.trim().length < 3) { toast.error("재현 가능한 데이터셋 버전을 입력하세요."); return; }
    if (!symbols.length) { toast.error("6자리 종목 코드를 하나 이상 입력하세요."); return; }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate) || !/^\d{4}-\d{2}-\d{2}$/.test(endDate)) { toast.error("수집 기간을 YYYY-MM-DD 형식으로 입력하세요."); return; }
    create.mutate({ name: name.trim(), versionKey: versionKey.trim(), universe: symbols.map(symbol => ({ symbol })), startDate, endDate, adjustmentBasis: "adjusted" });
  };
  return <section className="mb-5 frosted-panel rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold text-white">리서치 데이터셋</h2><p className="mt-1 max-w-2xl text-xs leading-relaxed text-slate-500">조건식 실험은 어떤 종목 유니버스·기간·가격 조정 기준을 사용했는지 고정해야 재현할 수 있습니다. 현재는 초안만 저장되며, 키움 실데이터 수집 뒤에 준비 상태로 전환됩니다.</p></div><Badge className="border-violet-300/20 bg-violet-300/10 text-violet-100">VERSIONED DATASET</Badge></div><div className="mt-4 grid gap-3 lg:grid-cols-6"><label className="text-[11px] text-slate-400 lg:col-span-2">데이터셋 이름<Input value={name} onChange={event => setName(event.target.value)} placeholder="예: KOSPI 모멘텀 연구" className="mt-1.5 border-slate-700 bg-slate-950/70 text-slate-100"/></label><label className="text-[11px] text-slate-400 lg:col-span-2">버전 키<Input value={versionKey} onChange={event => setVersionKey(event.target.value)} placeholder="예: krx-daily-2026-08-r1" className="mt-1.5 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label><label className="text-[11px] text-slate-400">시작일<Input value={startDate} onChange={event => setStartDate(event.target.value)} placeholder="YYYY-MM-DD" className="mt-1.5 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label><label className="text-[11px] text-slate-400">종료일<Input value={endDate} onChange={event => setEndDate(event.target.value)} placeholder="YYYY-MM-DD" className="mt-1.5 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label></div><label className="mt-3 block text-[11px] text-slate-400">유니버스 종목 코드 <span className="text-slate-600">공백 또는 쉼표로 구분</span><Textarea value={universeText} onChange={event => setUniverseText(event.target.value)} placeholder="005930, 000660, 035420" className="mt-1.5 min-h-20 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label><div className="mt-3 flex flex-wrap items-center justify-between gap-3"><p className="text-[11px] text-slate-500">유효 종목 <b className="font-mono text-teal-200">{symbols.length}</b>개 · 가격 조정 기준은 실데이터 수집 시 기록됩니다.</p><Button onClick={save} disabled={create.isPending} className="bg-violet-300 text-slate-950 hover:bg-violet-200"><Save className="mr-2" size={15}/>{create.isPending ? "초안 저장 중" : "데이터셋 초안 저장"}</Button></div>{datasets.isLoading ? <p className="mt-4 text-xs text-slate-500">저장된 데이터셋을 불러오는 중입니다.</p> : datasets.error ? <div className="mt-4 rounded-xl border border-amber-300/15 bg-amber-300/[0.05] p-3 text-xs text-amber-100">데이터셋 목록을 불러오지 못했습니다. {datasets.error.message}</div> : datasets.data?.length ? <div className="mt-4 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{datasets.data.slice(0, 6).map(dataset => <div key={dataset.id} className="rounded-xl border border-slate-800 bg-slate-950/35 p-3"><div className="flex items-center justify-between gap-2"><p className="truncate text-xs font-semibold text-slate-200">{dataset.name}</p><Badge className="border-slate-700 bg-slate-800 text-[9px] text-slate-300">{dataset.qualityStatus}</Badge></div><p className="mt-1 font-mono text-[10px] text-violet-200">{dataset.versionKey}</p><p className="mt-2 text-[10px] text-slate-500">{dataset.startDate} ~ {dataset.endDate} · {dataset.barCount.toLocaleString()} bars</p></div>)}</div> : <p className="mt-4 text-xs text-slate-500">저장된 데이터셋이 없습니다. 유니버스와 기간을 먼저 고정해 초안을 만드세요.</p>}</section>;
}

export function ResearchExperimentSpecPanel({ presetId, presetName }: { presetId: number | null; presetName?: string }) {
  const datasets = trpc.research.listDatasets.useQuery(undefined, { retry: false });
  const experiments = trpc.research.listExperiments.useQuery(undefined, { retry: false });
  const [datasetId, setDatasetId] = useState<number | null>(null); const [name, setName] = useState(""); const [strategyVersionLabel, setStrategyVersionLabel] = useState(""); const [cutoffDays, setCutoffDays] = useState("1");
  const [trainingStart, setTrainingStart] = useState(""); const [trainingEnd, setTrainingEnd] = useState(""); const [validationStart, setValidationStart] = useState(""); const [validationEnd, setValidationEnd] = useState("");
  const [entryTiming, setEntryTiming] = useState<"next_open" | "next_close">("next_open"); const [feeRate, setFeeRate] = useState("0.00015"); const [slippageBps, setSlippageBps] = useState("10"); const [holdingDays, setHoldingDays] = useState("5"); const [positions, setPositions] = useState("10");
  const create = trpc.research.createExperiment.useMutation({ onSuccess: async () => { await experiments.refetch(); toast.success("재현 가능한 실험 명세를 저장했습니다."); }, onError: error => toast.error(error.message) });
  const dataset = datasets.data?.find(item => item.id === datasetId);
  const save = () => {
    if (!presetId) { toast.error("실험으로 기록할 저장 조건식을 먼저 선택하세요."); return; }
    if (!dataset) { toast.error("고정할 데이터셋을 선택하세요."); return; }
    if (name.trim().length < 2 || strategyVersionLabel.trim().length < 2) { toast.error("실험 이름과 조건식 버전 라벨을 입력하세요."); return; }
    const dates = [trainingStart, trainingEnd, validationStart, validationEnd]; const hasAnyPeriod = dates.some(Boolean); const hasAllPeriod = dates.every(Boolean);
    if (hasAnyPeriod && !hasAllPeriod) { toast.error("학습·검증 기간의 시작일과 종료일을 모두 입력하세요."); return; }
    create.mutate({ datasetId: dataset.id, presetId, name: name.trim(), datasetVersionKey: dataset.versionKey, strategyVersionLabel: strategyVersionLabel.trim(), informationCutoffTradingDays: Number(cutoffDays), training: hasAllPeriod ? { startDate: trainingStart, endDate: trainingEnd } : undefined, validation: hasAllPeriod ? { startDate: validationStart, endDate: validationEnd } : undefined, assumptions: { entryTiming, feeRate: Number(feeRate), slippageBps: Number(slippageBps), maxHoldingDays: Number(holdingDays), maxConcurrentPositions: Number(positions) } });
  };
  return <section className="frosted-panel rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold text-white">실험 명세 저장</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">조건식·데이터셋·기간 분할·정보 절단·체결 및 비용 가정을 묶어 저장합니다.</p></div><Badge className="border-teal-300/20 bg-teal-300/10 text-teal-100">RESEARCH SPEC</Badge></div><p className="mt-3 rounded-xl border border-slate-800 bg-slate-950/35 px-3 py-2 text-xs text-slate-300">조건식 스냅샷: <b>{presetId ? `${presetName ?? "저장 조건식"} · #${presetId}` : "저장 조건식을 선택하세요"}</b></p><div className="mt-3 grid gap-3 md:grid-cols-2"><label className="text-[11px] text-slate-400">실험 이름<Input value={name} onChange={event => setName(event.target.value)} placeholder="예: 모멘텀 OOS" className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"/></label><label className="text-[11px] text-slate-400">조건식 버전 라벨<Input value={strategyVersionLabel} onChange={event => setStrategyVersionLabel(event.target.value)} placeholder="예: momentum-v2" className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label><label className="text-[11px] text-slate-400">고정 데이터셋<Select value={String(datasetId ?? "none")} onValueChange={value => setDatasetId(value === "none" ? null : Number(value))}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-slate-100"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">데이터셋 선택</SelectItem>{datasets.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.name} · {item.versionKey}</SelectItem>)}</SelectContent></Select></label><label className="text-[11px] text-slate-400">정보 절단 거래일<Input type="number" min={1} value={cutoffDays} onChange={event => setCutoffDays(event.target.value)} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-slate-100"/></label></div><div className="mt-3 grid gap-3 sm:grid-cols-2"><div className="rounded-xl border border-slate-800 bg-slate-950/25 p-3"><p className="text-[11px] font-semibold text-slate-300">학습 기간</p><div className="mt-2 grid grid-cols-2 gap-2"><Input aria-label="학습 시작일" value={trainingStart} onChange={event => setTrainingStart(event.target.value)} placeholder="YYYY-MM-DD" className="border-slate-700 bg-slate-950 font-mono text-xs text-slate-100"/><Input aria-label="학습 종료일" value={trainingEnd} onChange={event => setTrainingEnd(event.target.value)} placeholder="YYYY-MM-DD" className="border-slate-700 bg-slate-950 font-mono text-xs text-slate-100"/></div></div><div className="rounded-xl border border-slate-800 bg-slate-950/25 p-3"><p className="text-[11px] font-semibold text-slate-300">검증 기간</p><div className="mt-2 grid grid-cols-2 gap-2"><Input aria-label="검증 시작일" value={validationStart} onChange={event => setValidationStart(event.target.value)} placeholder="YYYY-MM-DD" className="border-slate-700 bg-slate-950 font-mono text-xs text-slate-100"/><Input aria-label="검증 종료일" value={validationEnd} onChange={event => setValidationEnd(event.target.value)} placeholder="YYYY-MM-DD" className="border-slate-700 bg-slate-950 font-mono text-xs text-slate-100"/></div></div></div><div className="mt-3 grid gap-3 sm:grid-cols-5"><label className="text-[10px] text-slate-500">체결 시점<Select value={entryTiming} onValueChange={value => setEntryTiming(value as "next_open" | "next_close")}><SelectTrigger className="mt-1 border-slate-700 bg-slate-950/70 text-xs text-slate-100"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="next_open">다음 시가</SelectItem><SelectItem value="next_close">다음 종가</SelectItem></SelectContent></Select></label><label className="text-[10px] text-slate-500">수수료율<Input value={feeRate} onChange={event => setFeeRate(event.target.value)} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-xs text-slate-100"/></label><label className="text-[10px] text-slate-500">슬리피지 bps<Input value={slippageBps} onChange={event => setSlippageBps(event.target.value)} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-xs text-slate-100"/></label><label className="text-[10px] text-slate-500">최대 보유일<Input value={holdingDays} onChange={event => setHoldingDays(event.target.value)} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-xs text-slate-100"/></label><label className="text-[10px] text-slate-500">최대 동시종목<Input value={positions} onChange={event => setPositions(event.target.value)} className="mt-1 border-slate-700 bg-slate-950/70 font-mono text-xs text-slate-100"/></label></div><div className="mt-4 flex flex-wrap items-center justify-between gap-3"><p className="max-w-xl text-[10px] leading-relaxed text-slate-500">기간을 입력하면 검증 기간은 학습 기간 뒤에 있어야 합니다. 공란이면 데이터셋 전체 기준의 초안을 저장합니다.</p><Button onClick={save} disabled={create.isPending || datasets.isLoading} className="bg-teal-300 text-slate-950 hover:bg-teal-200"><Save className="mr-2" size={15}/>{create.isPending ? "명세 저장 중" : "실험 명세 저장"}</Button></div>{datasets.error && <p className="mt-3 text-xs text-amber-200">데이터셋 목록 오류: {datasets.error.message}</p>}{experiments.data?.length ? <p className="mt-3 text-[11px] text-slate-500">저장된 실험 명세 {experiments.data.length}건</p> : null}</section>;
}

export function Backtest() {
  const utils = trpc.useUtils();
  const presets = trpc.presets.list.useQuery(undefined, { retry: false });
  const runs = trpc.backtests.list.useQuery(undefined, { retry: false });
  const [selectedPresetId, setSelectedPresetId] = useState<string>("");
  const [symbol, setSymbol] = useState("005930");
  const [initialCapital, setInitialCapital] = useState("10000000");
  const [holdingDays, setHoldingDays] = useState("5");
  const selectedPreset = presets.data?.find(item => String(item.id) === selectedPresetId);
  const validSymbol = /^\d{6}$/.test(symbol);
  const dailyBars = trpc.quant.dailyBars.useQuery({ symbol, maxPages: 3 }, { retry: false, enabled: Boolean(selectedPresetId) && validSymbol });
  const run = trpc.backtests.run.useMutation({ onSuccess: () => { utils.backtests.list.invalidate(); toast.success("실데이터 백테스트 결과를 저장했습니다."); }, onError: error => toast.error(error.message) });
  const execute = () => {
    const capital = Number(initialCapital); const days = Number(holdingDays);
    if (!selectedPresetId || !dailyBars.data?.bars || dailyBars.data.bars.length < 60) { toast.error("최소 60개의 실제 일봉이 수집된 뒤 실행할 수 있습니다."); return; }
    if (!Number.isInteger(capital) || capital <= 0 || !Number.isInteger(days) || days < 1 || days > 60) { toast.error("자본금과 보유 기간을 확인하세요."); return; }
    run.mutate({ presetId: Number(selectedPresetId), bars: dailyBars.data.bars, initialCapital: capital, holdingDays: days, minScore: 70, feeRate: 0.00015 });
  };
  const relevantRuns = runs.data?.filter(item => !selectedPresetId || String(item.presetId) === selectedPresetId) ?? [];
  if (presets.isLoading || runs.isLoading) return <div className="enter-soft"><PageHeader eyebrow="REPRODUCIBLE RESEARCH" title="백테스트 스튜디오"/><section className="frosted-panel flex min-h-72 flex-col items-center justify-center rounded-2xl text-center"><Loader2 className="mb-3 animate-spin text-teal-300" size={26}/><p className="text-sm font-semibold text-slate-300">리서치 설정과 저장된 실험 결과를 불러오는 중입니다.</p></section></div>;
  if (presets.error || runs.error) return <div className="enter-soft"><PageHeader eyebrow="REPRODUCIBLE RESEARCH" title="백테스트 스튜디오"/><section className="frosted-panel flex min-h-72 flex-col items-center justify-center rounded-2xl px-6 text-center"><CircleAlert className="mb-3 text-amber-300" size={26}/><p className="text-sm font-semibold text-slate-200">리서치 실험 데이터를 불러오지 못했습니다.</p><p className="mt-2 max-w-md text-xs leading-relaxed text-slate-500">{presets.error?.message ?? runs.error?.message}</p><Button className="mt-5 bg-teal-300 text-slate-950 hover:bg-teal-200" onClick={() => { presets.refetch(); runs.refetch(); }}>다시 시도</Button></section></div>;
  return <div className="enter-soft"><PageHeader eyebrow="REPRODUCIBLE RESEARCH" title="백테스트 스튜디오"><Badge className="border-amber-300/20 bg-amber-300/10 text-amber-200">DAILY DATASET REQUIRED</Badge></PageHeader><ResearchProtocolPanel/><ResearchDatasetPanel/><div className="grid gap-5 xl:grid-cols-[0.82fr_1.18fr]"><section className="frosted-panel rounded-2xl p-5"><h2 className="font-bold text-white">전략·데이터 선택</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">저장된 조건식과 키움 ka10081에서 수집한 실제 일봉만 사용합니다.</p><Select value={selectedPresetId} onValueChange={setSelectedPresetId}><SelectTrigger className="mt-5 border-slate-700 bg-slate-900 text-slate-100"><SelectValue placeholder="저장된 프리셋 선택" /></SelectTrigger><SelectContent>{presets.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.name}</SelectItem>)}</SelectContent></Select><label className="mt-4 block text-xs text-slate-400">종목 코드<Input value={symbol} onChange={event => setSymbol(event.target.value.replace(/\D/g, "").slice(0, 6))} className="mt-2 border-slate-700 bg-slate-900 font-mono text-slate-100" /></label><div className="mt-4 grid grid-cols-2 gap-3"><label className="text-xs text-slate-400">초기 자본금<Input value={initialCapital} onChange={event => setInitialCapital(event.target.value.replace(/\D/g, ""))} className="mt-2 border-slate-700 bg-slate-900 font-mono text-slate-100" /></label><label className="text-xs text-slate-400">보유 기간(일)<Input value={holdingDays} onChange={event => setHoldingDays(event.target.value.replace(/\D/g, ""))} className="mt-2 border-slate-700 bg-slate-900 font-mono text-slate-100" /></label></div>{selectedPreset ? <div className="mt-4 rounded-xl border border-teal-300/15 bg-teal-300/[0.04] p-3.5"><p className="text-sm font-semibold text-teal-100">{selectedPreset.name}</p><p className="mt-1 text-xs text-slate-400">{selectedPreset.description ?? "저장된 조건식"}</p></div> : <p className="mt-4 text-xs text-slate-500">저장된 프리셋을 선택해 실행할 수 있습니다.</p>}<div className="mt-5 rounded-xl border border-slate-800 bg-slate-950/30 p-3.5"><p className="text-xs font-semibold text-slate-200">일봉 데이터 준비 상태</p><p className="mt-1 text-xs text-slate-500">{dailyBars.isLoading ? "실제 일봉을 수집하는 중입니다." : dailyBars.data ? `${dailyBars.data.bars.length}개 실제 일봉 준비됨` : "프리셋과 6자리 종목 코드를 선택하면 수집합니다."}</p>{dailyBars.error && <p className="mt-2 text-xs text-amber-200">{dailyBars.error.message}</p>}</div><Button onClick={execute} disabled={run.isPending || dailyBars.isLoading || !selectedPresetId || (dailyBars.data?.bars.length ?? 0) < 60} className="mt-5 w-full bg-teal-300 text-slate-950 hover:bg-teal-200"><Play className="mr-2" size={15}/>{run.isPending ? "실험 실행 중" : "리서치 백테스트 실행"}</Button><p className="mt-3 text-[10px] leading-relaxed text-slate-500">수수료 가정 0.015% · 최소 복합 점수 70 · 예시 시세나 임의 수익률은 사용하지 않습니다.</p></section><section className="frosted-panel rounded-2xl p-5"><div className="flex items-start justify-between"><div><h2 className="font-bold text-white">저장된 실험 결과</h2><p className="mt-1 text-xs text-slate-500">실제 일봉으로 완료된 결과만 표시합니다.</p></div><LineChart className="text-slate-500" size={19} /></div>{relevantRuns.length ? <div className="mt-5 space-y-3">{relevantRuns.map(item => <div key={item.id} className="rounded-xl border border-slate-800 bg-slate-950/35 p-4"><div className="flex items-center justify-between gap-3"><span className="font-mono text-[10px] text-slate-500">{item.startDate} ~ {item.endDate}</span><Badge className="border-slate-700 bg-slate-800 text-slate-300">{item.status}</Badge></div><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4"><div><p className="text-[10px] text-slate-500">총 수익률</p><p className="mt-1 font-mono text-sm text-teal-200">{item.totalReturn ?? "—"}%</p></div><div><p className="text-[10px] text-slate-500">승률</p><p className="mt-1 font-mono text-sm text-slate-200">{item.winRate ?? "—"}%</p></div><div><p className="text-[10px] text-slate-500">거래 수</p><p className="mt-1 font-mono text-sm text-slate-200">{item.tradeCount ?? "—"}</p></div><div><p className="text-[10px] text-slate-500">최대 낙폭</p><p className="mt-1 font-mono text-sm text-rose-200">{item.maxDrawdown ?? "—"}%</p></div></div></div>)}</div> : <div className="flex min-h-64 flex-col items-center justify-center text-center"><LineChart className="mb-3 text-slate-600" size={28} /><p className="text-sm font-semibold text-slate-300">저장된 리서치 실험이 없습니다.</p><p className="mt-2 max-w-sm text-xs leading-relaxed text-slate-500">일봉 데이터셋이 준비된 뒤 실행한 결과만 이 영역에 표시됩니다.</p></div>}</section></div></div>;
}

function SafetySettings() {
  const utils = trpc.useUtils();
  const query = trpc.tradingProfile.get.useQuery(undefined, { retry: false });
  const [maxBuyAmount, setMaxBuyAmount] = useState("");
  const [dailyTradeLimit, setDailyTradeLimit] = useState("");
  const [killSwitch, setKillSwitch] = useState(true);
  const [autoTradeEnabled, setAutoTradeEnabled] = useState(false);
  const save = trpc.tradingProfile.saveSafety.useMutation({ onSuccess: () => { utils.tradingProfile.get.invalidate(); toast.success("실거래 안전 설정을 저장했습니다."); }, onError: error => toast.error(error.message) });
  useEffect(() => { const profile = query.data?.profile; if (!profile) return; setMaxBuyAmount(String(profile.maxBuyAmount)); setDailyTradeLimit(String(profile.dailyTradeLimit)); setKillSwitch(profile.killSwitch); setAutoTradeEnabled(profile.autoTradeEnabled); }, [query.data?.profile]);
  const submit = () => { const amount = Number(maxBuyAmount); const limit = Number(dailyTradeLimit); if (!Number.isInteger(amount) || amount < 10_000 || !Number.isInteger(limit) || limit < 1) { toast.error("매수 상한과 일일 거래 횟수는 유효한 값으로 입력하세요."); return; } save.mutate({ maxBuyAmount: amount, dailyTradeLimit: limit, killSwitch, autoTradeEnabled, refreshIntervalSeconds: query.data?.profile?.refreshIntervalSeconds ?? 300 }); };
  return <section className="frosted-panel rounded-2xl p-5"><div className="flex items-center justify-between"><div><h2 className="font-bold text-white">주문 안전 제한</h2><p className="mt-1 text-xs text-slate-500">서버에 저장되며 주문 생성·전송 단계에서 다시 검증됩니다.</p></div><ShieldCheck className="text-teal-300" size={23} /></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-xs text-slate-400">1회 매수 상한<Input value={maxBuyAmount} onChange={event => setMaxBuyAmount(event.target.value)} inputMode="numeric" placeholder="예: 500000" className="mt-2 border-slate-700 bg-slate-900 font-mono text-slate-100" /></label><label className="text-xs text-slate-400">일일 거래 횟수<Input value={dailyTradeLimit} onChange={event => setDailyTradeLimit(event.target.value)} inputMode="numeric" placeholder="예: 3" className="mt-2 border-slate-700 bg-slate-900 font-mono text-slate-100" /></label></div><div className="mt-5 space-y-3 rounded-xl border border-slate-800 bg-slate-950/30 p-4"><div className="flex items-center justify-between"><div><p className="text-sm font-semibold text-slate-200">자동매매 활성화</p><p className="mt-1 text-xs text-slate-500">지정 IP·운영 API 검증 후에만 실제 전송이 허용됩니다.</p></div><Switch checked={autoTradeEnabled} onCheckedChange={setAutoTradeEnabled} /></div><div className="h-px bg-slate-800"/><div className="flex items-center justify-between"><div><p className="text-sm font-semibold text-slate-200">킬 스위치</p><p className="mt-1 text-xs text-amber-300">켜면 신규 실주문이 차단됩니다.</p></div><Switch checked={killSwitch} onCheckedChange={setKillSwitch} /></div></div><Button onClick={submit} disabled={save.isPending || query.isLoading} className="mt-5 bg-teal-300 text-slate-950 hover:bg-teal-200"><Save className="mr-2" size={15}/>{save.isPending ? "저장 중" : "안전 설정 저장"}</Button></section>;
}

function AutoTradePolicySettings() {
  const utils = trpc.useUtils();
  const query = trpc.tradingProfile.getAutoPolicy.useQuery(undefined, { retry: false });
  const [totalCapital, setTotalCapital] = useState("10000000");
  const [maxPositions, setMaxPositions] = useState("5");
  const [stopLoss, setStopLoss] = useState("2");
  const [takeProfit, setTakeProfit] = useState("3");
  const [dailyLoss, setDailyLoss] = useState("3");
  const save = trpc.tradingProfile.saveAutoPolicy.useMutation({ onSuccess: data => { utils.tradingProfile.getAutoPolicy.invalidate(); toast.success(`자동 실투 정책 v${data.version}을 저장했습니다.`); }, onError: error => toast.error(error.message) });
  useEffect(() => { const policy = query.data?.policy; if (policy) { setTotalCapital(String(policy.totalCapital)); setMaxPositions(String(policy.maxConcurrentPositions)); setStopLoss(String(policy.stopLossPercent)); setTakeProfit(String(policy.takeProfitPercent)); setDailyLoss(String(policy.dailyLossLimitPercent)); } }, [query.data?.policy]);
  const submit = () => { const input = { totalCapital: Number(totalCapital), maxConcurrentPositions: Number(maxPositions), stopLossPercent: Number(stopLoss), takeProfitPercent: Number(takeProfit), dailyLossLimitPercent: Number(dailyLoss) }; if (!Number.isInteger(input.totalCapital) || input.totalCapital < 100_000 || !Number.isInteger(input.maxConcurrentPositions) || input.maxConcurrentPositions < 1 || [input.stopLossPercent, input.takeProfitPercent, input.dailyLossLimitPercent].some(value => !Number.isFinite(value) || value <= 0)) { toast.error("자동 실투 정책 값을 확인하세요."); return; } save.mutate(input); };
  const policy = query.data?.policy;
  return <section className="frosted-panel rounded-2xl p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-bold text-white">자동 실투 정책</h2><p className="mt-1 text-xs leading-relaxed text-slate-500">변경은 다음 신규 진입부터 적용되며, 기존 포지션·손익은 당시 정책 버전을 보존합니다.</p></div><Badge className="border-violet-300/20 bg-violet-300/10 text-violet-100">{policy ? `v${policy.version}` : "미저장"}</Badge></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><label className="text-xs text-slate-400">총 운용 자본<Input value={totalCapital} onChange={event => setTotalCapital(event.target.value)} inputMode="numeric" className="mt-2 border-slate-700 bg-slate-900 font-mono text-slate-100"/></label><label className="text-xs text-slate-400">최대 동시 보유<Input value={maxPositions} onChange={event => setMaxPositions(event.target.value)} inputMode="numeric" className="mt-2 border-slate-700 bg-slate-900 font-mono text-slate-100"/></label><label className="text-xs text-slate-400">손절률 (%)<Input value={stopLoss} onChange={event => setStopLoss(event.target.value)} inputMode="decimal" className="mt-2 border-slate-700 bg-slate-900 font-mono text-slate-100"/></label><label className="text-xs text-slate-400">익절률 (%)<Input value={takeProfit} onChange={event => setTakeProfit(event.target.value)} inputMode="decimal" className="mt-2 border-slate-700 bg-slate-900 font-mono text-slate-100"/></label><label className="text-xs text-slate-400 sm:col-span-2">일일 누적 손실 차단률 (%)<Input value={dailyLoss} onChange={event => setDailyLoss(event.target.value)} inputMode="decimal" className="mt-2 border-slate-700 bg-slate-900 font-mono text-slate-100"/></label></div><Button onClick={submit} disabled={save.isPending || query.isLoading} className="mt-5 bg-violet-300 text-slate-950 hover:bg-violet-200"><Save className="mr-2" size={15}/>{save.isPending ? "저장 중" : "자동 실투 정책 저장"}</Button></section>;
}

function Execution() {
  const rankings = trpc.rankings.latest.useQuery(undefined, { retry: false });
  const candidates = rankings.data?.items ?? [];
  return <div className="enter-soft"><PageHeader eyebrow="ORDER DRAFT · CONFIRMATION" title="주문 초안 · 전송 전 확인"><Badge className="border-amber-300/20 bg-amber-300/10 px-2.5 py-1 text-amber-200 hover:bg-amber-300/10"><LockKeyhole className="mr-1.5" size={13} />자동 주문 준비</Badge></PageHeader><div className="grid gap-5 xl:grid-cols-[1fr_0.95fr]"><div className="space-y-5"><SafetySettings /><AutoTradePolicySettings /></div><section className="frosted-panel rounded-2xl p-5"><div className="flex items-center justify-between"><div><h2 className="font-bold text-white">실제 가격 기반 주문 후보</h2><p className="mt-1 text-xs text-slate-500">저장된 조건 충족 랭킹은 후보일 뿐, 매수·전송·체결을 뜻하지 않습니다.</p></div><Badge className="border-slate-700 bg-slate-900 text-slate-300">CANDIDATE ONLY</Badge></div>{candidates.length ? <div className="mt-5 space-y-2">{candidates.slice(0, 5).map(item => <div key={item.id} className="flex items-center justify-between rounded-xl border border-slate-800 bg-slate-950/35 p-3"><div><p className="text-sm font-semibold text-slate-200">{item.name}</p><p className="mt-1 font-mono text-[10px] text-slate-500">{item.symbol} · 점수 {Number(item.score).toFixed(1)}</p></div><span className="font-mono text-xs text-slate-300">{item.price.toLocaleString()}원</span></div>)}</div> : <div className="flex min-h-48 flex-col items-center justify-center text-center"><CircleAlert className="mb-3 text-slate-600" size={24} /><p className="text-sm font-semibold text-slate-300">실제 가격 기반 주문 후보가 없습니다.</p><p className="mt-2 text-xs leading-relaxed text-slate-500">키움 OAuth와 장중 가격 관찰이 완료되면 조건식 후보가 표시됩니다.</p></div>}</section></div><OrderDraftPanel /></div>;
}

function ObservationView() {
  const observations = trpc.paperPortfolio.latestActualObservations.useQuery({ limit: 30 }, { retry: false, refetchInterval: 60_000 });
  return <div className="enter-soft"><PageHeader eyebrow="INTRADAY ACTUAL PRICE OBSERVATION" title="장중 실제 가격 관찰"><Badge className="border-sky-300/20 bg-sky-300/10 px-2.5 py-1 text-sky-100 hover:bg-sky-300/10"><Activity className="mr-1.5" size={13}/>매수 아님</Badge></PageHeader><section className="frosted-panel overflow-hidden rounded-2xl"><div className="border-b border-slate-800 p-5"><h2 className="font-bold text-white">조건식 후보의 실제 가격 스냅샷</h2><p className="mt-1 max-w-3xl text-xs leading-relaxed text-slate-500">키움 원본에서 저장된 가격·신호만 표시합니다. 이 목록은 관찰 기록이며, 실제 매수·모의 진입·주문 전송을 의미하지 않습니다.</p></div>{observations.isLoading ? <div className="flex min-h-64 items-center justify-center text-sm text-slate-500">실제 가격 관찰을 조회하는 중입니다.</div> : observations.error ? <div className="flex min-h-64 flex-col items-center justify-center px-6 text-center"><CircleAlert className="mb-3 text-rose-300" size={24}/><p className="text-sm font-semibold text-slate-300">실제 가격 관찰을 불러오지 못했습니다.</p><p className="mt-2 text-xs text-slate-500">{observations.error.message}</p></div> : observations.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left"><thead className="border-b border-slate-800 text-[10px] uppercase tracking-wider text-slate-500"><tr><th className="px-5 py-3">종목</th><th className="px-2 py-3 text-right">관찰가</th><th className="px-2 py-3 text-right">등락률</th><th className="px-2 py-3">근거</th><th className="px-5 py-3 text-right">수집 시각</th></tr></thead><tbody>{observations.data.map(item => <tr key={item.id} className="border-b border-slate-800/50 text-sm"><td className="px-5 py-4"><p className="font-semibold text-slate-100">{item.name ?? item.symbol}</p><p className="mt-0.5 font-mono text-[10px] text-slate-500">{item.symbol}</p></td><td className="px-2 py-4 text-right font-mono text-xs text-slate-200">{item.price.toLocaleString()}원</td><td className="px-2 py-4 text-right font-mono text-xs text-teal-200">{item.changeRate === null ? "—" : `${Number(item.changeRate).toFixed(2)}%`}</td><td className="px-2 py-4 font-mono text-[10px] text-slate-500">{item.source}</td><td className="px-5 py-4 text-right font-mono text-xs text-slate-400">{new Date(item.capturedAt).toLocaleString("ko-KR")}</td></tr>)}</tbody></table></div> : <div className="flex min-h-64 flex-col items-center justify-center px-6 text-center"><Activity className="mb-3 text-slate-600" size={24}/><p className="text-sm font-semibold text-slate-300">아직 실제 가격 관찰 기록이 없습니다.</p><p className="mt-2 text-xs text-slate-500">키움 OAuth와 장중 수집이 완료되면 조건식 후보의 실제 가격이 이곳에 표시됩니다.</p></div>}</section></div>;
}

function PaperPortfolioView() {
  return <div className="enter-soft"><PageHeader eyebrow="PAPER PORTFOLIO · ACTUAL PRICE EVIDENCE" title="실제 가격 기반 모의 포트폴리오"><Badge className="border-violet-300/20 bg-violet-300/10 px-2.5 py-1 text-violet-100 hover:bg-violet-300/10"><WalletCards className="mr-1.5" size={13}/>모의 추적</Badge></PageHeader><p className="mb-5 max-w-3xl text-sm leading-relaxed text-slate-400">이 화면의 진입·보유·청산은 키움에서 저장된 실제 가격을 근거로 한 연구용 모의 포지션입니다. 실제 계좌 매수나 브로커 체결과는 별개입니다.</p><PaperPortfolioPanel /></div>;
}

function DayTradingExperimentView() {
  return <div className="enter-soft"><PageHeader eyebrow="INTRADAY PAPER EXPERIMENT · ACTUAL MARKET SNAPSHOTS" title="당일 데이트레이드 실시간 모의투자 조건식"><Badge className="border-violet-300/20 bg-violet-300/10 px-2.5 py-1 text-violet-100 hover:bg-violet-300/10"><TrendingUp className="mr-1.5" size={13}/>실제 시세 · 모의 체결</Badge></PageHeader><DayTradingExperimentPanel /></div>;
}

export function ActivityView() {
  const utils = trpc.useUtils();
  const positions = trpc.account.listPositions.useQuery(undefined, { retry: false, refetchInterval: 60_000 });
  const orders = trpc.orders.list.useQuery(undefined, { retry: false, refetchInterval: 60_000 });
  const executions = trpc.orders.listExecutions.useQuery(undefined, { retry: false, refetchInterval: 60_000 });
  const sync = trpc.account.syncPositions.useMutation({ onSuccess: () => { utils.account.listPositions.invalidate(); toast.success("실제 계좌 스냅샷을 동기화했습니다."); }, onError: error => toast.error(error.message) });
  const loadingSources = [positions.isLoading && "포지션·평가손익", orders.isLoading && "주문 의도", executions.isLoading && "전송·체결 기록"].filter(Boolean);
  if (loadingSources.length) return <div className="enter-soft"><PageHeader eyebrow="ACCOUNT OVERVIEW" title="실거래 주문 · 포지션"/><section className="frosted-panel flex min-h-72 flex-col items-center justify-center px-6 text-center"><Loader2 className="mb-3 animate-spin text-teal-300" size={24}/><p className="text-sm font-semibold text-slate-200">실제 거래 상태를 조회하는 중입니다.</p><p className="mt-2 text-xs text-slate-500">{loadingSources.join(" · ")} 데이터를 불러오고 있습니다.</p></section></div>;
  const queryError = positions.error ?? orders.error ?? executions.error;
  const retryQueries = () => { positions.refetch(); orders.refetch(); executions.refetch(); };
  if (queryError) return <div className="enter-soft"><PageHeader eyebrow="ACCOUNT OVERVIEW" title="실거래 주문 · 포지션"/><section className="frosted-panel flex min-h-72 flex-col items-center justify-center px-6 text-center"><CircleAlert className="mb-3 text-rose-300" size={24}/><p className="text-sm font-semibold text-slate-200">실제 계좌·주문·체결 기록을 불러오지 못했습니다.</p><p className="mt-2 max-w-md text-xs leading-relaxed text-slate-500">{queryError.message} 지정 단말·OAuth 상태가 준비된 뒤 다시 시도하세요.</p><Button onClick={retryQueries} variant="outline" className="mt-5 border-slate-700 bg-slate-900 text-slate-200 hover:bg-slate-800 hover:text-white"><RefreshCw className="mr-2" size={15}/>다시 시도</Button></section></div>;
  return <div className="enter-soft"><PageHeader eyebrow="ACCOUNT OVERVIEW" title="실거래 주문 · 포지션"><Button onClick={() => sync.mutate()} disabled={sync.isPending} variant="outline" className="border-slate-700 bg-slate-900 text-slate-200 hover:bg-slate-800 hover:text-white"><RefreshCw className={cn("mr-2", sync.isPending && "animate-spin")} size={15} />실제 계좌 동기화</Button></PageHeader><div className="grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><section className="frosted-panel overflow-hidden rounded-2xl"><div className="flex items-center justify-between border-b border-slate-800 p-5"><div><h2 className="font-bold text-white">보유 포지션 · 평가손익</h2><p className="mt-1 text-xs text-slate-500">키움 계좌에서 수집·저장된 최신 스냅샷만 표시합니다.</p></div></div>{positions.isLoading ? <div className="flex min-h-64 items-center justify-center text-sm text-slate-500">실제 포지션을 조회하는 중입니다.</div> : positions.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[520px] text-left"><thead className="border-b border-slate-800 text-[10px] uppercase tracking-wider text-slate-500"><tr><th className="px-5 py-3">종목</th><th className="px-2 py-3 text-right">보유</th><th className="px-2 py-3 text-right">평균가</th><th className="px-5 py-3 text-right">평가손익</th></tr></thead><tbody>{positions.data.map(item => <tr key={item.symbol} className="border-b border-slate-800/50 text-sm"><td className="px-5 py-4"><p className="font-semibold text-slate-100">{item.name}</p><p className="mt-0.5 font-mono text-[10px] text-slate-500">{item.symbol}</p></td><td className="px-2 py-4 text-right font-mono text-xs text-slate-300">{item.quantity.toLocaleString()}주</td><td className="px-2 py-4 text-right font-mono text-xs text-slate-300">{item.averagePrice.toLocaleString()}원</td><td className="px-5 py-4 text-right"><p className={cn("font-mono text-xs", item.profitLoss >= 0 ? "text-teal-200" : "text-rose-300")}>{item.profitLoss.toLocaleString()}원</p><p className="mt-0.5 font-mono text-[10px] text-slate-500">{Number(item.profitLossRate).toFixed(2)}%</p></td></tr>)}</tbody></table></div> : <div className="flex min-h-64 flex-col items-center justify-center px-6 text-center"><BriefcaseBusiness className="mb-3 text-slate-600" size={24}/><p className="text-sm font-semibold text-slate-300">표시할 실제 포지션 데이터가 없습니다.</p><p className="mt-2 text-xs text-slate-500">지정 IP 등록 후 실제 계좌 동기화를 실행하세요.</p></div>}</section><section className="space-y-5"><section className="frosted-panel rounded-2xl p-5"><div className="flex items-center justify-between"><div><h2 className="font-bold text-white">실제 전송 · 체결</h2><p className="mt-1 text-xs text-slate-500">운영자 소유 주문 의도에 연결된 브로커 응답 기록</p></div><MoreHorizontal size={17} className="text-slate-500"/></div>{executions.isLoading ? <p className="py-6 text-xs text-slate-500">체결 기록을 조회하는 중입니다.</p> : executions.data?.length ? <div className="mt-4 space-y-2">{executions.data.map(item => <div key={item.id} className="rounded-xl border border-slate-800 bg-slate-950/35 p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-semibold text-slate-200">{item.name} <span className="font-mono text-[10px] text-slate-500">{item.symbol}</span></p><span className="rounded-full bg-slate-800 px-2 py-1 font-mono text-[10px] text-slate-300">{item.executionStatus}</span></div><p className="mt-1 font-mono text-[10px] text-slate-500">{item.side === "buy" ? "매수" : "매도"} · 주문 {item.quantity.toLocaleString()}주 · 체결 {item.filledQuantity.toLocaleString()}주{item.filledPrice ? ` · ${item.filledPrice.toLocaleString()}원` : ""}</p></div>)}</div> : <p className="py-6 text-center text-xs text-slate-500">표시할 실제 전송·체결 기록이 없습니다.</p>}</section><section className="frosted-panel rounded-2xl p-5"><h2 className="font-bold text-white">최근 주문 의도</h2>{orders.data?.length ? <div className="mt-4 space-y-2">{orders.data.map(item => <div key={item.id} className="flex items-center gap-3 rounded-lg bg-slate-950/35 px-3 py-2"><div className="min-w-0 flex-1"><p className="text-xs font-semibold text-slate-200">{item.name}</p><p className="font-mono text-[10px] text-slate-500">{item.symbol} · {item.quantity.toLocaleString()}주</p></div><span className="rounded-full bg-slate-800 px-2 py-1 text-[10px] text-slate-300">{item.status}</span></div>)}</div> : <p className="py-6 text-center text-xs text-slate-500">실제 주문 기록이 없습니다.</p>}</section></section></div></div>;
}

function LegacySettingsView() { const status = trpc.quant.brokerStatus.useQuery(undefined, { retry: false }); const broker = status.data; return <div className="hidden">{broker?.mode}</div>; }

function ConnectionStateRow({ title, status, detail, tone }: { title: string; status: string; detail: string; tone: "ready" | "warning" | "error" | "muted" }) {
  const color = tone === "ready" ? "text-teal-200" : tone === "warning" ? "text-amber-200" : tone === "error" ? "text-rose-300" : "text-slate-400";
  return <div className="rounded-xl border border-slate-800 bg-slate-950/35 p-3.5"><div className="flex items-center justify-between gap-4"><p className="text-xs font-semibold text-slate-200">{title}</p><span className={cn("shrink-0 text-xs font-semibold", color)}>{status}</span></div><p className="mt-1.5 text-[11px] leading-relaxed text-slate-500">{detail}</p></div>;
}

function SettingsView() {
  const status = trpc.quant.brokerStatus.useQuery(undefined, { retry: false });
  const broker = status.data;
  const access = presentKiwoomAccess(broker?.fixedIpRegistered);
  const oauth = presentOAuthStatus(broker?.oauth);
  return <div className="enter-soft"><PageHeader eyebrow="INTEGRATION & CONTROL" title="키움 운영 API 연동"><Badge className={cn("border", broker?.hasCredentials ? "border-teal-300/20 bg-teal-300/10 text-teal-200" : "border-amber-300/20 bg-amber-300/10 text-amber-200")}><CircleAlert className="mr-1.5" size={13}/>{broker?.hasCredentials ? "운영 자격 증명 저장됨" : "운영 자격 증명 확인 필요"}</Badge></PageHeader><div className="grid gap-5 xl:grid-cols-[0.95fr_1.05fr]"><section className="frosted-panel rounded-2xl p-5"><div className="flex items-start justify-between"><div><h2 className="font-bold text-white">서버 비밀 자격 증명</h2><p className="mt-1 max-w-md text-xs leading-relaxed text-slate-500">App Key·App Secret·계좌번호는 브라우저에 표시하거나 앱에서 수정하지 않습니다.</p></div><LockKeyhole className="text-teal-300" size={20}/></div><div className="mt-6 space-y-3"><ConnectionStateRow title="실행 환경" status="LIVE" detail="키움 운영 API를 대상으로 동작합니다." tone="ready"/><ConnectionStateRow title="키움 REST API 접근" status={access.label} detail={access.detail} tone={access.tone}/></div></section><section className="frosted-panel rounded-2xl p-5"><h2 className="font-bold text-white">연결 상태</h2><p className="mt-1 text-xs text-slate-500">상태는 서버의 키움 API 연결 정보를 읽기 전용으로 표시합니다.</p><div className="mt-5 space-y-3"><ConnectionStateRow title="OAuth 접근 토큰" status={oauth.label} detail={oauth.detail} tone={oauth.tone}/><ConnectionStateRow title="일봉·계좌 조회" status={broker?.fixedIpRegistered ? "준비" : "차단"} detail={broker?.fixedIpRegistered ? "OAuth 검증 후 실제 수집 요청을 실행할 수 있습니다." : "키움 접근 인증이 확인되기 전까지 브로커 요청은 서버에서 차단됩니다."} tone={broker?.fixedIpRegistered ? "ready" : "warning"}/><ConnectionStateRow title="실거래 주문 전송" status={broker?.mayTransmitOrders ? "허용" : "차단"} detail={broker?.mayTransmitOrders ? "최종 확인·안전 한도 검증을 통과한 주문만 전송됩니다." : "미검증 접근 상태 또는 별도 주문 전송 승인 전에는 서버에서 차단됩니다."} tone={broker?.mayTransmitOrders ? "ready" : "warning"}/></div></section></div></div>;
}

export default function Home() { const [active, setActive] = useState<Page>("lab"); const [menuOpen, setMenuOpen] = useState(false); const query = new URLSearchParams(window.location.search); const initialDeck = query.get("deck") === "random" ? "random" : "survivor"; const selectedSize = Number(query.get("size")); const initialCombinationCount = selectedSize === 100 || selectedSize === 1_000 || selectedSize === 3_000 ? selectedSize : 1_000; const content = useMemo(() => { if (active === "lab") return <StrategyArenaLab initialDeck={initialDeck} initialCombinationCount={initialCombinationCount} />; if (active === "builder") return <Builder />; if (active === "chart") return <ChartView />; if (active === "backtest") return <Backtest />; if (active === "observation") return <ObservationView />; if (active === "daytrade") return <DayTradingExperimentView />; if (active === "paper") return <PaperPortfolioView />; if (active === "execution") return <Execution />; if (active === "activity") return <ActivityView />; return <ResearchDashboard setActive={setActive} />; }, [active, initialDeck, initialCombinationCount]); return <OperatorAccessGate><div data-ui-version="strategy-arena-lab-v1" className="operator-workspace min-h-screen bg-[#090e16] text-slate-100"><Sidebar active={active} setActive={setActive} open={menuOpen} setOpen={setMenuOpen} /><main className="min-w-0"><header className="flex h-16 items-center justify-between bg-[#0b111a]/80 px-5 backdrop-blur-md lg:px-8"><div className="flex min-w-0 items-center gap-3"><button aria-label="기능 메뉴 열기" onClick={() => setMenuOpen(true)} className="inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-slate-800/80 text-slate-100 transition hover:bg-teal-300 hover:text-slate-950"><Menu size={20} /></button><div><p className="text-xs font-semibold text-slate-300">STRATEGY ARENA · OPERATOR LAB</p><p className="mt-0.5 hidden font-mono text-[10px] text-slate-500 sm:block">원본 · 배틀 · 결과 · 실행 모드 분리</p></div></div><div className="flex items-center gap-2"><OperatorAccount /></div></header><div className="mx-auto max-w-[1720px] px-4 py-6 sm:px-6 lg:px-10">{content}</div></main></div></OperatorAccessGate>; }
